window.VLONTO = window.VLONTO || {};
window.VLONTO["vlonto_ontology_ttl"] = "# VLOnto - Vietnamese Legal Ontology, version 1.0.0 (release v1)\n# OWL 2 ontology in Turtle. Namespace https://tmquan.github.io/VLOnto/ontology# (prefix vlo:).\n# Instance IRIs of the knowledge graph use https://tmquan.github.io/VLOnto/id/ (prefix vlid:).\n# Every VLOnto class and property has rdfs:label in English and Vietnamese, an English skos:definition,\n# and a vlo:module annotation used by the 3D ontology playground to colour terms by module.\n\n@prefix vlo:     <https://tmquan.github.io/VLOnto/ontology#> .\n@prefix vlid:    <https://tmquan.github.io/VLOnto/id/> .\n@prefix owl:     <http://www.w3.org/2002/07/owl#> .\n@prefix rdf:     <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .\n@prefix rdfs:    <http://www.w3.org/2000/01/rdf-schema#> .\n@prefix xsd:     <http://www.w3.org/2001/XMLSchema#> .\n@prefix skos:    <http://www.w3.org/2004/02/skos/core#> .\n@prefix dcterms: <http://purl.org/dc/terms/> .\n@prefix prov:    <http://www.w3.org/ns/prov#> .\n@prefix schema:  <https://schema.org/> .\n@prefix org:     <http://www.w3.org/ns/org#> .\n@prefix eli:     <http://data.europa.eu/eli/ontology#> .\n@prefix vann:    <http://purl.org/vocab/vann/> .\n\n# =====================================================================================================\n# Ontology header\n# =====================================================================================================\n\n<https://tmquan.github.io/VLOnto/ontology>\n    a owl:Ontology ;\n    dcterms:title \"VLOnto: Vietnamese Legal Ontology\"@en , \"VLOnto: Bản thể học pháp luật Việt Nam\"@vi ;\n    dcterms:description \"\"\"VLOnto describes Vietnamese legal documents and their provisions, the bodies that issue them, their validity and the dated events that replace, amend or repeal them, legal-basis and citation links, court decisions and case-law precedents, legal questions and answers, legal terminology, legal news and the classification schemes used to organise them. Terms are aligned with ELI (European Legislation Identifier), SKOS, DCTERMS, PROV-O, schema.org and the W3C Organization ontology by sub-class and sub-property axioms. The VLOnto knowledge graph instantiates the ontology from public datasets of Vietnamese legal material: release 1.0.0 uses the four thuvienphapluat.vn datasets (legal documents, legal Q&As, legal terminology and legal news); court decisions, courts and precedents are modelled by the judiciary module and are populated from release 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn).\"\"\"@en ,\n        \"\"\"VLOnto mô tả văn bản pháp luật Việt Nam và các điều, khoản của chúng, cơ quan ban hành, tình trạng hiệu lực và các sự kiện thay thế, sửa đổi, bãi bỏ văn bản, quan hệ căn cứ pháp lý và trích dẫn, bản án, quyết định của Tòa án và án lệ, hỏi đáp pháp luật, thuật ngữ pháp lý, tin tức pháp luật và các hệ thống phân loại. Các khái niệm được liên kết với ELI, SKOS, DCTERMS, PROV-O, schema.org và W3C Organization bằng tiên đề lớp con và thuộc tính con. Đồ thị tri thức VLOnto được xây dựng từ các bộ dữ liệu công khai về pháp luật Việt Nam: phiên bản 1.0.0 dùng bốn bộ dữ liệu của thuvienphapluat.vn (văn bản pháp luật, hỏi đáp pháp luật, thuật ngữ pháp lý và tin tức pháp luật); bản án, quyết định, tòa án và án lệ được mô tả trong mô-đun tư pháp và có dữ liệu từ phiên bản 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn).\"\"\"@vi ;\n    owl:versionInfo \"1.0.0\" ;\n    owl:versionIRI <https://tmquan.github.io/VLOnto/ontology/1.0.0> ;\n    owl:priorVersion <https://tmquan.github.io/VLOnto/ontology/0.1.0> ;\n    dcterms:license <https://creativecommons.org/licenses/by/4.0/> ;\n    dcterms:creator [ a schema:Person ; schema:name \"tmquan\" ; schema:url \"https://github.com/tmquan\"^^xsd:anyURI ] ;\n    dcterms:created \"2026-11-11\"^^xsd:date ;\n    dcterms:modified \"2026-11-12\"^^xsd:date ;\n    dcterms:rights \"CC BY 4.0. Not an official legal text and not legal advice.\"@en ;\n    vann:preferredNamespacePrefix \"vlo\" ;\n    vann:preferredNamespaceUri \"https://tmquan.github.io/VLOnto/ontology#\" ;\n    rdfs:seeAlso <https://tmquan.github.io/VLOnto/> , <https://github.com/tmquan/VLOnto> , <https://arxiv.org/abs/2611.11426> ;\n    dcterms:source <https://huggingface.co/datasets/tmquan/thuvienphapluat-vn-vbpl> ,\n        <https://huggingface.co/datasets/tmquan/thuvienphapluat-vn-hdpl> ,\n        <https://huggingface.co/datasets/tmquan/thuvienphapluat-vn-tnpl> ,\n        <https://huggingface.co/datasets/tmquan/thuvienphapluat-vn-htpl> ;\n    skos:editorialNote \"Release 1.0.0 (v1): the knowledge graph is built from the four thuvienphapluat.vn datasets tmquan/thuvienphapluat-vn-vbpl, -hdpl, -tnpl and -htpl. The court datasets tmquan/anle-toaan-gov-vn and tmquan/cbba-toaan-gov-vn are planned for release 2.0; the judiciary classes and properties are kept in the ontology and marked with a scope note.\"@en ,\n        \"Phiên bản 1.0.0 (v1): đồ thị tri thức được xây dựng từ bốn bộ dữ liệu của thuvienphapluat.vn: tmquan/thuvienphapluat-vn-vbpl, -hdpl, -tnpl và -htpl. Các bộ dữ liệu tòa án tmquan/anle-toaan-gov-vn và tmquan/cbba-toaan-gov-vn được dự kiến đưa vào phiên bản 2.0; các lớp và thuộc tính của mô-đun tư pháp vẫn được giữ trong bản thể và có ghi chú phạm vi.\"@vi .\n\n# =====================================================================================================\n# Annotation properties and the module scheme\n# =====================================================================================================\n\nvlo:module\n    a owl:AnnotationProperty ;\n    rdfs:label \"module\"@en , \"mô-đun\"@vi ;\n    skos:definition \"The thematic module of VLOnto to which a class, property or concept scheme belongs; used to group and colour terms in documentation and in the 3D ontology playground.\"@en ;\n    rdfs:range vlo:Module ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ;\n    vlo:module vlo:module-provenance .\n\nvlo:typeConcept\n    a owl:AnnotationProperty ;\n    rdfs:label \"type concept\"@en , \"khái niệm loại văn bản\"@vi ;\n    skos:definition \"Links a VLOnto document class to the concept of the DocumentType scheme that represents the same document type, so that class membership and the eli:type_document value can be kept in step.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ;\n    vlo:module vlo:module-classification .\n\nvlo:Module\n    a owl:Class ;\n    rdfs:subClassOf skos:Concept ;\n    rdfs:label \"Module\"@en , \"Mô-đun bản thể\"@vi ;\n    skos:definition \"A thematic group of VLOnto terms, such as documents, provisions or judiciary.\"@en ;\n    skos:definition \"Một nhóm chủ đề của các khái niệm VLOnto, ví dụ văn bản, điều khoản hay tư pháp.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ;\n    vlo:module vlo:module-provenance .\n\nvlo:ModuleScheme\n    a skos:ConceptScheme ;\n    rdfs:label \"VLOnto modules\"@en , \"Các mô-đun của VLOnto\"@vi ;\n    skos:definition \"The eleven thematic modules of VLOnto.\"@en ;\n    vlo:module vlo:module-provenance ;\n    skos:hasTopConcept vlo:module-documents , vlo:module-provisions , vlo:module-agents , vlo:module-validity-change ,\n        vlo:module-citation-basis , vlo:module-judiciary , vlo:module-qa , vlo:module-terminology , vlo:module-news ,\n        vlo:module-classification , vlo:module-provenance .\n\nvlo:module-documents a vlo:Module , owl:NamedIndividual ; skos:inScheme vlo:ModuleScheme ; skos:topConceptOf vlo:ModuleScheme ; skos:notation \"documents\" ;\n    skos:prefLabel \"documents\"@en , \"văn bản\"@vi ; skos:definition \"Legal documents and their types.\"@en .\nvlo:module-provisions a vlo:Module , owl:NamedIndividual ; skos:inScheme vlo:ModuleScheme ; skos:topConceptOf vlo:ModuleScheme ; skos:notation \"provisions\" ;\n    skos:prefLabel \"provisions\"@en , \"điều khoản\"@vi ; skos:definition \"Structural units of legal documents: parts, chapters, sections, articles, clauses, points and appendices.\"@en .\nvlo:module-agents a vlo:Module , owl:NamedIndividual ; skos:inScheme vlo:ModuleScheme ; skos:topConceptOf vlo:ModuleScheme ; skos:notation \"agents\" ;\n    skos:prefLabel \"agents\"@en , \"chủ thể\"@vi ; skos:definition \"Public authorities that issue documents or decide cases.\"@en .\nvlo:module-validity-change a vlo:Module , owl:NamedIndividual ; skos:inScheme vlo:ModuleScheme ; skos:topConceptOf vlo:ModuleScheme ; skos:notation \"validity-change\" ;\n    skos:prefLabel \"validity and change\"@en , \"hiệu lực và thay đổi\"@vi ; skos:definition \"Validity status of documents and the dated events that replace, amend, repeal or terminate them.\"@en .\nvlo:module-citation-basis a vlo:Module , owl:NamedIndividual ; skos:inScheme vlo:ModuleScheme ; skos:topConceptOf vlo:ModuleScheme ; skos:notation \"citation-basis\" ;\n    skos:prefLabel \"citation and legal basis\"@en , \"trích dẫn và căn cứ\"@vi ; skos:definition \"Legal-basis and citation links between legal resources and from other works to legal resources.\"@en .\nvlo:module-judiciary a vlo:Module , owl:NamedIndividual ; skos:inScheme vlo:ModuleScheme ; skos:topConceptOf vlo:ModuleScheme ; skos:notation \"judiciary\" ;\n    skos:prefLabel \"judiciary\"@en , \"tư pháp\"@vi ; skos:definition \"Court decisions, judgments, precedents and their classification.\"@en ;\n    skos:scopeNote \"The terms of this module are populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn); the VLOnto 1.0.0 knowledge graph has no court data.\"@en ,\n        \"Các khái niệm của mô-đun này có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn); đồ thị tri thức VLOnto 1.0.0 chưa có dữ liệu tòa án.\"@vi .\nvlo:module-qa a vlo:Module , owl:NamedIndividual ; skos:inScheme vlo:ModuleScheme ; skos:topConceptOf vlo:ModuleScheme ; skos:notation \"qa\" ;\n    skos:prefLabel \"legal Q&A\"@en , \"hỏi đáp pháp luật\"@vi ; skos:definition \"Published legal questions and their answers.\"@en .\nvlo:module-terminology a vlo:Module , owl:NamedIndividual ; skos:inScheme vlo:ModuleScheme ; skos:topConceptOf vlo:ModuleScheme ; skos:notation \"terminology\" ;\n    skos:prefLabel \"terminology\"@en , \"thuật ngữ\"@vi ; skos:definition \"Legal terms organised as SKOS concepts.\"@en .\nvlo:module-news a vlo:Module , owl:NamedIndividual ; skos:inScheme vlo:ModuleScheme ; skos:topConceptOf vlo:ModuleScheme ; skos:notation \"news\" ;\n    skos:prefLabel \"news\"@en , \"tin tức\"@vi ; skos:definition \"Legal news and policy articles that mention legal documents.\"@en .\nvlo:module-classification a vlo:Module , owl:NamedIndividual ; skos:inScheme vlo:ModuleScheme ; skos:topConceptOf vlo:ModuleScheme ; skos:notation \"classification\" ;\n    skos:prefLabel \"classification\"@en , \"phân loại\"@vi ; skos:definition \"Concept schemes for legal areas, document types and legal-force ranks.\"@en .\nvlo:module-provenance a vlo:Module , owl:NamedIndividual ; skos:inScheme vlo:ModuleScheme ; skos:topConceptOf vlo:ModuleScheme ; skos:notation \"provenance\" ;\n    skos:prefLabel \"provenance\"@en , \"nguồn gốc\"@vi ; skos:definition \"Source datasets, extraction methods, edge sets and build activities.\"@en .\n\n# =====================================================================================================\n# External terms referenced by alignment axioms (declarations only)\n# =====================================================================================================\n\neli:LegalResource a owl:Class ; rdfs:label \"Legal resource (ELI)\"@en ; rdfs:isDefinedBy <http://data.europa.eu/eli/ontology> .\neli:LegalResourceSubdivision a owl:Class ; rdfs:label \"Legal resource subdivision (ELI)\"@en ; rdfs:isDefinedBy <http://data.europa.eu/eli/ontology> .\neli:ResourceType a owl:Class ; rdfs:label \"Resource type (ELI)\"@en ; rdfs:isDefinedBy <http://data.europa.eu/eli/ontology> .\neli:InForce a owl:Class ; rdfs:label \"In force (ELI)\"@en ; rdfs:isDefinedBy <http://data.europa.eu/eli/ontology> .\neli:is_part_of a owl:ObjectProperty ; rdfs:label \"is part of (ELI)\"@en ; rdfs:isDefinedBy <http://data.europa.eu/eli/ontology> .\neli:has_part a owl:ObjectProperty ; rdfs:label \"has part (ELI)\"@en ; rdfs:isDefinedBy <http://data.europa.eu/eli/ontology> .\neli:cites a owl:ObjectProperty ; rdfs:label \"cites (ELI)\"@en ; rdfs:isDefinedBy <http://data.europa.eu/eli/ontology> .\neli:based_on a owl:ObjectProperty ; rdfs:label \"based on (ELI)\"@en ; rdfs:isDefinedBy <http://data.europa.eu/eli/ontology> .\neli:changes a owl:ObjectProperty ; rdfs:label \"changes (ELI)\"@en ; rdfs:isDefinedBy <http://data.europa.eu/eli/ontology> .\neli:amends a owl:ObjectProperty ; rdfs:label \"amends (ELI)\"@en ; rdfs:isDefinedBy <http://data.europa.eu/eli/ontology> .\neli:repeals a owl:ObjectProperty ; rdfs:label \"repeals (ELI)\"@en ; rdfs:isDefinedBy <http://data.europa.eu/eli/ontology> .\neli:in_force a owl:ObjectProperty ; rdfs:label \"in force (ELI)\"@en ; rdfs:isDefinedBy <http://data.europa.eu/eli/ontology> .\neli:type_document a owl:ObjectProperty ; rdfs:label \"type of document (ELI)\"@en ; rdfs:isDefinedBy <http://data.europa.eu/eli/ontology> .\neli:passed_by a owl:ObjectProperty ; rdfs:label \"passed by (ELI)\"@en ; rdfs:isDefinedBy <http://data.europa.eu/eli/ontology> .\neli:first_date_entry_in_force a owl:DatatypeProperty ; rdfs:label \"first date of entry into force (ELI)\"@en ; rdfs:isDefinedBy <http://data.europa.eu/eli/ontology> .\neli:date_no_longer_in_force a owl:DatatypeProperty ; rdfs:label \"date no longer in force (ELI)\"@en ; rdfs:isDefinedBy <http://data.europa.eu/eli/ontology> .\neli:date_document a owl:DatatypeProperty ; rdfs:label \"date of document (ELI)\"@en ; rdfs:isDefinedBy <http://data.europa.eu/eli/ontology> .\neli:id_local a owl:DatatypeProperty ; rdfs:label \"local identifier (ELI)\"@en ; rdfs:isDefinedBy <http://data.europa.eu/eli/ontology> .\n\nskos:Concept a owl:Class ; rdfs:label \"Concept (SKOS)\"@en ; rdfs:isDefinedBy <http://www.w3.org/2004/02/skos/core> .\nskos:ConceptScheme a owl:Class ; rdfs:label \"Concept scheme (SKOS)\"@en ; rdfs:isDefinedBy <http://www.w3.org/2004/02/skos/core> .\nskos:related a owl:ObjectProperty ; rdfs:label \"related (SKOS)\"@en ; rdfs:isDefinedBy <http://www.w3.org/2004/02/skos/core> .\nprov:Entity a owl:Class ; rdfs:label \"Entity (PROV)\"@en ; rdfs:isDefinedBy <http://www.w3.org/ns/prov-o#> .\nprov:Activity a owl:Class ; rdfs:label \"Activity (PROV)\"@en ; rdfs:isDefinedBy <http://www.w3.org/ns/prov-o#> .\nprov:Plan a owl:Class ; rdfs:label \"Plan (PROV)\"@en ; rdfs:isDefinedBy <http://www.w3.org/ns/prov-o#> .\nprov:wasGeneratedBy a owl:ObjectProperty ; rdfs:label \"was generated by (PROV)\"@en ; rdfs:isDefinedBy <http://www.w3.org/ns/prov-o#> .\nprov:used a owl:ObjectProperty ; rdfs:label \"used (PROV)\"@en ; rdfs:isDefinedBy <http://www.w3.org/ns/prov-o#> .\nprov:startedAtTime a owl:DatatypeProperty ; rdfs:label \"started at time (PROV)\"@en ; rdfs:isDefinedBy <http://www.w3.org/ns/prov-o#> .\norg:Organization a owl:Class ; rdfs:label \"Organization (ORG)\"@en ; rdfs:isDefinedBy <http://www.w3.org/ns/org#> .\nschema:CreativeWork a owl:Class ; rdfs:label \"Creative work (schema.org)\"@en ; rdfs:isDefinedBy <https://schema.org/> .\nschema:Legislation a owl:Class ; rdfs:label \"Legislation (schema.org)\"@en ; rdfs:isDefinedBy <https://schema.org/> .\nschema:Question a owl:Class ; rdfs:label \"Question (schema.org)\"@en ; rdfs:isDefinedBy <https://schema.org/> .\nschema:Answer a owl:Class ; rdfs:label \"Answer (schema.org)\"@en ; rdfs:isDefinedBy <https://schema.org/> .\nschema:NewsArticle a owl:Class ; rdfs:label \"News article (schema.org)\"@en ; rdfs:isDefinedBy <https://schema.org/> .\nschema:acceptedAnswer a owl:ObjectProperty ; rdfs:label \"accepted answer (schema.org)\"@en ; rdfs:isDefinedBy <https://schema.org/> .\nschema:citation a owl:ObjectProperty ; rdfs:label \"citation (schema.org)\"@en ; rdfs:isDefinedBy <https://schema.org/> .\nschema:mentions a owl:ObjectProperty ; rdfs:label \"mentions (schema.org)\"@en ; rdfs:isDefinedBy <https://schema.org/> .\nschema:url a owl:DatatypeProperty ; rdfs:label \"url (schema.org)\"@en ; rdfs:isDefinedBy <https://schema.org/> .\ndcterms:references a owl:ObjectProperty ; rdfs:label \"references (DCTERMS)\"@en ; rdfs:isDefinedBy <http://purl.org/dc/terms/> .\ndcterms:subject a owl:ObjectProperty ; rdfs:label \"subject (DCTERMS)\"@en ; rdfs:isDefinedBy <http://purl.org/dc/terms/> .\ndcterms:source a owl:ObjectProperty ; rdfs:label \"source (DCTERMS)\"@en ; rdfs:isDefinedBy <http://purl.org/dc/terms/> .\ndcterms:creator a owl:ObjectProperty ; rdfs:label \"creator (DCTERMS)\"@en ; rdfs:isDefinedBy <http://purl.org/dc/terms/> .\ndcterms:license a owl:ObjectProperty ; rdfs:label \"license (DCTERMS)\"@en ; rdfs:isDefinedBy <http://purl.org/dc/terms/> .\ndcterms:title a owl:DatatypeProperty ; rdfs:label \"title (DCTERMS)\"@en ; rdfs:isDefinedBy <http://purl.org/dc/terms/> .\ndcterms:identifier a owl:DatatypeProperty ; rdfs:label \"identifier (DCTERMS)\"@en ; rdfs:isDefinedBy <http://purl.org/dc/terms/> .\ndcterms:issued a owl:DatatypeProperty ; rdfs:label \"issued (DCTERMS)\"@en ; rdfs:isDefinedBy <http://purl.org/dc/terms/> .\ndcterms:date a owl:DatatypeProperty ; rdfs:label \"date (DCTERMS)\"@en ; rdfs:isDefinedBy <http://purl.org/dc/terms/> .\ndcterms:description a owl:AnnotationProperty .\ndcterms:created a owl:AnnotationProperty .\ndcterms:modified a owl:AnnotationProperty .\ndcterms:rights a owl:AnnotationProperty .\nvann:preferredNamespacePrefix a owl:AnnotationProperty .\nvann:preferredNamespaceUri a owl:AnnotationProperty .\nskos:definition a owl:AnnotationProperty .\nskos:prefLabel a owl:AnnotationProperty .\nskos:notation a owl:AnnotationProperty .\nskos:inScheme a owl:AnnotationProperty .\nskos:topConceptOf a owl:AnnotationProperty .\nskos:hasTopConcept a owl:AnnotationProperty .\nschema:name a owl:AnnotationProperty .\n\n# =====================================================================================================\n# Module: documents\n# =====================================================================================================\n\nvlo:LegalDocument\n    a owl:Class ;\n    rdfs:subClassOf eli:LegalResource , schema:Legislation ;\n    rdfs:label \"Legal document\"@en , \"Văn bản pháp luật\"@vi ;\n    skos:definition \"A document issued by a competent state body that has legal effect, identified by its type, number and issue date.\"@en ;\n    skos:definition \"Văn bản do cơ quan nhà nước có thẩm quyền ban hành, có hiệu lực pháp lý, được xác định bởi loại, số, ký hiệu và ngày ban hành.\"@vi ;\n    rdfs:comment \"In the VLOnto knowledge graph every legal document comes from the thuvienphapluat-vn-vbpl dataset and is one of the 40,816 in-scope normative documents of the processed corpus.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ;\n    vlo:module vlo:module-documents .\n\nvlo:NormativeLegalDocument\n    a owl:Class ;\n    rdfs:subClassOf vlo:LegalDocument ;\n    rdfs:label \"Normative legal document\"@en , \"Văn bản quy phạm pháp luật\"@vi ;\n    skos:definition \"A legal document containing generally binding rules of conduct, issued in the form, order and procedure set out by the Law on Promulgation of Legal Normative Documents.\"@en ;\n    skos:definition \"Văn bản có chứa quy phạm pháp luật, được ban hành theo đúng thẩm quyền, hình thức, trình tự, thủ tục do Luật Ban hành văn bản quy phạm pháp luật quy định.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ;\n    vlo:module vlo:module-documents .\n\nvlo:Constitution a owl:Class ; rdfs:subClassOf vlo:NormativeLegalDocument ;\n    rdfs:label \"Constitution\"@en , \"Hiến pháp\"@vi ;\n    skos:definition \"The fundamental law of the State, adopted by the National Assembly; it has the highest legal force.\"@en ;\n    skos:definition \"Đạo luật cơ bản của Nhà nước do Quốc hội thông qua, có hiệu lực pháp lý cao nhất.\"@vi ;\n    vlo:typeConcept vlo:doctype-constitution ; rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-documents .\n\nvlo:Code a owl:Class ; rdfs:subClassOf vlo:NormativeLegalDocument ;\n    rdfs:label \"Code\"@en , \"Bộ luật\"@vi ;\n    skos:definition \"A comprehensive law adopted by the National Assembly that systematically regulates a whole field, such as the Civil Code or the Labour Code.\"@en ;\n    skos:definition \"Văn bản luật do Quốc hội thông qua, điều chỉnh một cách có hệ thống một lĩnh vực, ví dụ Bộ luật Dân sự, Bộ luật Lao động.\"@vi ;\n    vlo:typeConcept vlo:doctype-code ; rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-documents .\n\nvlo:Law a owl:Class ; rdfs:subClassOf vlo:NormativeLegalDocument ;\n    rdfs:label \"Law\"@en , \"Luật\"@vi ;\n    skos:definition \"A statute adopted by the National Assembly.\"@en ;\n    skos:definition \"Văn bản luật do Quốc hội thông qua.\"@vi ;\n    vlo:typeConcept vlo:doctype-law ; rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-documents .\n\nvlo:Ordinance a owl:Class ; rdfs:subClassOf vlo:NormativeLegalDocument ;\n    rdfs:label \"Ordinance\"@en , \"Pháp lệnh\"@vi ;\n    skos:definition \"A normative document adopted by the Standing Committee of the National Assembly on matters assigned by the National Assembly.\"@en ;\n    skos:definition \"Văn bản quy phạm pháp luật do Ủy ban Thường vụ Quốc hội ban hành về những vấn đề được Quốc hội giao.\"@vi ;\n    vlo:typeConcept vlo:doctype-ordinance ; rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-documents .\n\nvlo:Resolution a owl:Class ; rdfs:subClassOf vlo:NormativeLegalDocument ;\n    rdfs:label \"Resolution\"@en , \"Nghị quyết\"@vi ;\n    skos:definition \"A normative resolution issued by a collegial body such as the National Assembly, its Standing Committee, the Government or the Council of Judges of the Supreme People's Court.\"@en ;\n    skos:definition \"Nghị quyết quy phạm pháp luật do cơ quan tập thể ban hành, như Quốc hội, Ủy ban Thường vụ Quốc hội, Chính phủ hoặc Hội đồng Thẩm phán Tòa án nhân dân tối cao.\"@vi ;\n    vlo:typeConcept vlo:doctype-resolution ; rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-documents .\n\nvlo:JointResolution a owl:Class ; rdfs:subClassOf vlo:NormativeLegalDocument ;\n    rdfs:label \"Joint resolution\"@en , \"Nghị quyết liên tịch\"@vi ;\n    skos:definition \"A resolution issued jointly by a state body and the central body of a socio-political organisation, for example the Standing Committee of the National Assembly or the Government together with the Presidium of the Viet Nam Fatherland Front.\"@en ;\n    skos:definition \"Nghị quyết do cơ quan nhà nước và cơ quan trung ương của tổ chức chính trị - xã hội cùng ban hành.\"@vi ;\n    vlo:typeConcept vlo:doctype-joint-resolution ; rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-documents .\n\nvlo:Decree a owl:Class ; rdfs:subClassOf vlo:NormativeLegalDocument ;\n    rdfs:label \"Decree\"@en , \"Nghị định\"@vi ;\n    skos:definition \"A normative document issued by the Government, usually detailing or implementing laws.\"@en ;\n    skos:definition \"Văn bản quy phạm pháp luật do Chính phủ ban hành, thường quy định chi tiết hoặc hướng dẫn thi hành luật.\"@vi ;\n    vlo:typeConcept vlo:doctype-decree ; rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-documents .\n\nvlo:Decision a owl:Class ; rdfs:subClassOf vlo:NormativeLegalDocument ;\n    rdfs:label \"Decision\"@en , \"Quyết định\"@vi ;\n    skos:definition \"A normative decision issued by the Prime Minister, a minister or another competent head of a central body; only decisions numbered in the normative form N/YYYY/CODE are in scope.\"@en ;\n    skos:definition \"Quyết định quy phạm pháp luật của Thủ tướng Chính phủ, Bộ trưởng hoặc người đứng đầu cơ quan trung ương có thẩm quyền; chỉ các quyết định có số dạng N/YYYY/KÝ-HIỆU thuộc phạm vi.\"@vi ;\n    vlo:typeConcept vlo:doctype-decision ; rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-documents .\n\nvlo:Circular a owl:Class ; rdfs:subClassOf vlo:NormativeLegalDocument ;\n    rdfs:label \"Circular\"@en , \"Thông tư\"@vi ;\n    skos:definition \"A normative document issued by a minister or the head of a ministerial-level agency, the Chief Justice of the Supreme People's Court, the Prosecutor General or the State Auditor General.\"@en ;\n    skos:definition \"Văn bản quy phạm pháp luật do Bộ trưởng, Thủ trưởng cơ quan ngang bộ, Chánh án Tòa án nhân dân tối cao, Viện trưởng Viện kiểm sát nhân dân tối cao hoặc Tổng Kiểm toán nhà nước ban hành.\"@vi ;\n    vlo:typeConcept vlo:doctype-circular ; rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-documents .\n\nvlo:JointCircular a owl:Class ; rdfs:subClassOf vlo:NormativeLegalDocument ;\n    rdfs:label \"Joint circular\"@en , \"Thông tư liên tịch\"@vi ;\n    skos:definition \"A circular issued jointly by two or more ministers, heads of ministerial-level agencies or judicial bodies.\"@en ;\n    skos:definition \"Thông tư do hai hay nhiều Bộ trưởng, Thủ trưởng cơ quan ngang bộ hoặc cơ quan tư pháp cùng ban hành.\"@vi ;\n    vlo:typeConcept vlo:doctype-joint-circular ; rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-documents .\n\n[] a owl:AllDisjointClasses ;\n    owl:members ( vlo:Constitution vlo:Code vlo:Law vlo:Ordinance vlo:Resolution vlo:JointResolution vlo:Decree vlo:Decision vlo:Circular vlo:JointCircular ) .\n\n# =====================================================================================================\n# Module: provisions\n# =====================================================================================================\n\nvlo:Provision\n    a owl:Class ;\n    rdfs:subClassOf eli:LegalResourceSubdivision ;\n    rdfs:label \"Provision\"@en , \"Đơn vị cấu trúc của văn bản\"@vi ;\n    skos:definition \"A structural unit of a legal document, such as a part, chapter, section, article, clause, point or appendix.\"@en ;\n    skos:definition \"Một đơn vị cấu trúc của văn bản pháp luật như phần, chương, mục, điều, khoản, điểm hoặc phụ lục.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ;\n    vlo:module vlo:module-provisions .\n\nvlo:Part a owl:Class ; rdfs:subClassOf vlo:Provision ;\n    rdfs:label \"Part\"@en , \"Phần\"@vi ;\n    skos:definition \"A top-level division of a long legal document, grouping chapters (Phần thứ nhất, Phần thứ hai, ...).\"@en ;\n    skos:definition \"Đơn vị lớn nhất trong văn bản dài, gồm nhiều chương.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provisions .\n\nvlo:Chapter a owl:Class ; rdfs:subClassOf vlo:Provision ;\n    rdfs:label \"Chapter\"@en , \"Chương\"@vi ;\n    skos:definition \"A division of a legal document grouping sections or articles under a heading (Chương I, Chương II, ...).\"@en ;\n    skos:definition \"Đơn vị của văn bản gồm các mục hoặc điều có cùng đề mục.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provisions .\n\nvlo:Section a owl:Class ; rdfs:subClassOf vlo:Provision ;\n    rdfs:label \"Section\"@en , \"Mục\"@vi ;\n    skos:definition \"A division of a chapter grouping articles (Mục 1, Mục 2, ...).\"@en ;\n    skos:definition \"Đơn vị của chương, gồm các điều.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provisions .\n\nvlo:Article a owl:Class ; rdfs:subClassOf vlo:Provision ;\n    rdfs:label \"Article\"@en , \"Điều\"@vi ;\n    skos:definition \"The basic numbered unit of a legal document (Điều N), usually with a heading, divided into clauses.\"@en ;\n    skos:definition \"Đơn vị cơ bản được đánh số của văn bản (Điều N), thường có tên điều và gồm các khoản.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provisions .\n\nvlo:Clause a owl:Class ; rdfs:subClassOf vlo:Provision ;\n    rdfs:label \"Clause\"@en , \"Khoản\"@vi ;\n    skos:definition \"A numbered subdivision of an article (khoản 1, khoản 2, ...).\"@en ;\n    skos:definition \"Đơn vị được đánh số trong một điều (khoản 1, khoản 2, ...).\"@vi ;\n    rdfs:comment \"In the knowledge graph clauses are created only when a citation, applied-provision or answer edge refers to them.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provisions .\n\nvlo:Point a owl:Class ; rdfs:subClassOf vlo:Provision ;\n    rdfs:label \"Point\"@en , \"Điểm\"@vi ;\n    skos:definition \"A lettered subdivision of a clause (điểm a, điểm b, ...).\"@en ;\n    skos:definition \"Đơn vị được đánh chữ cái trong một khoản (điểm a, điểm b, ...).\"@vi ;\n    rdfs:comment \"In the knowledge graph points are created only when a citation, applied-provision or answer edge refers to them.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provisions .\n\nvlo:Appendix a owl:Class ; rdfs:subClassOf vlo:Provision ;\n    rdfs:label \"Appendix\"@en , \"Phụ lục\"@vi ;\n    skos:definition \"An attachment issued with a legal document, such as a regulation, charter or list promulgated by the document; it may contain its own articles.\"@en ;\n    skos:definition \"Văn bản kèm theo (quy định, quy chế, điều lệ, danh mục) được ban hành kèm theo văn bản; có thể có các điều riêng.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provisions .\n\n[] a owl:AllDisjointClasses ;\n    owl:members ( vlo:Part vlo:Chapter vlo:Section vlo:Article vlo:Clause vlo:Point vlo:Appendix ) .\n\nvlo:LegalDocument owl:disjointWith vlo:Provision .\n\n# =====================================================================================================\n# Module: agents\n# =====================================================================================================\n\nvlo:PublicAuthority\n    a owl:Class ;\n    rdfs:subClassOf org:Organization ;\n    rdfs:label \"Public authority\"@en , \"Cơ quan nhà nước\"@vi ;\n    skos:definition \"A state organisation or office holder acting for the State, such as the National Assembly, the Government, a ministry, the Prime Minister or a court.\"@en ;\n    skos:definition \"Tổ chức hoặc chức danh nhà nước, như Quốc hội, Chính phủ, bộ, Thủ tướng Chính phủ hoặc Tòa án.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-agents .\n\nvlo:IssuingBody\n    a owl:Class ;\n    rdfs:subClassOf vlo:PublicAuthority ;\n    rdfs:label \"Issuing body\"@en , \"Cơ quan ban hành\"@vi ;\n    skos:definition \"A public authority that issues legal documents, identified in the knowledge graph by the issuer code used in document numbers (for example BTC for the Ministry of Finance).\"@en ;\n    skos:definition \"Cơ quan nhà nước ban hành văn bản pháp luật, được xác định bằng ký hiệu cơ quan trong số văn bản (ví dụ BTC là Bộ Tài chính).\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-agents .\n\nvlo:Court\n    a owl:Class ;\n    rdfs:subClassOf vlo:PublicAuthority ;\n    rdfs:label \"Court\"@en , \"Tòa án\"@vi ;\n    skos:definition \"A people's court or military court that decides cases; identified by its official name, for example Tòa án nhân dân tỉnh Cà Mau.\"@en ;\n    skos:definition \"Tòa án nhân dân hoặc Tòa án quân sự xét xử các vụ việc; được xác định bằng tên chính thức.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-agents ;\n    skos:scopeNote \"Populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn); the VLOnto 1.0.0 knowledge graph has no data for this term.\"@en ,\n        \"Có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn); đồ thị tri thức VLOnto 1.0.0 chưa có dữ liệu cho khái niệm này.\"@vi .\n\n# =====================================================================================================\n# Module: validity-change\n# =====================================================================================================\n\nvlo:LegalChange\n    a owl:Class ;\n    rdfs:subClassOf prov:Activity ;\n    rdfs:label \"Legal change\"@en , \"Sự kiện thay đổi hiệu lực văn bản\"@vi ;\n    skos:definition \"A dated event in which an acting legal document replaces, amends, repeals, partially repeals or partially terminates an affected legal document. The event is reified so that its kind, effective date, the evidence sentence and the extraction method can be recorded; the direct shortcut properties (vlo:replaces, vlo:amends, ...) carry the same information without the details.\"@en ;\n    skos:definition \"Sự kiện có ngày hiệu lực, trong đó một văn bản thay thế, sửa đổi bổ sung, bãi bỏ, bãi bỏ một phần hoặc làm hết hiệu lực một phần văn bản khác; được biểu diễn thành nút để ghi loại thay đổi, ngày hiệu lực, câu chứng cứ và phương pháp trích xuất.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:ChangeKind\n    a owl:Class ;\n    rdfs:subClassOf skos:Concept ;\n    rdfs:label \"Change kind\"@en , \"Loại thay đổi\"@vi ;\n    skos:definition \"A kind of legal change: replaced, amended, repealed, partially repealed or partially terminated.\"@en ;\n    skos:definition \"Loại thay đổi: thay thế, sửa đổi bổ sung, bãi bỏ, bãi bỏ một phần, hết hiệu lực một phần.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:ValidityStatus\n    a owl:Class ;\n    rdfs:subClassOf skos:Concept , eli:InForce ;\n    rdfs:label \"Validity status\"@en , \"Tình trạng hiệu lực\"@vi ;\n    skos:definition \"The validity of a legal document as of the knowledge-graph date, combining the curated source status with text-extracted change relations (validity rules v7). It refines the ELI in-force concept with eight values.\"@en ;\n    skos:definition \"Tình trạng hiệu lực của văn bản tại ngày tính của đồ thị, kết hợp trạng thái từ nguồn với các quan hệ thay đổi trích xuất từ văn bản (bộ luật v7).\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\n# =====================================================================================================\n# Module: judiciary\n# =====================================================================================================\n\nvlo:JudicialDocument\n    a owl:Class ;\n    rdfs:subClassOf schema:CreativeWork ;\n    rdfs:label \"Judicial document\"@en , \"Văn bản của Tòa án\"@vi ;\n    skos:definition \"A document produced in the judicial system: a court decision in a case or a published case-law precedent.\"@en ;\n    skos:definition \"Văn bản trong hoạt động xét xử: bản án, quyết định của Tòa án hoặc án lệ đã công bố.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn); the VLOnto 1.0.0 knowledge graph has no data for this term.\"@en ,\n        \"Có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn); đồ thị tri thức VLOnto 1.0.0 chưa có dữ liệu cho khái niệm này.\"@vi .\n\nvlo:CourtDecision\n    a owl:Class ;\n    rdfs:subClassOf vlo:JudicialDocument ;\n    rdfs:label \"Court decision\"@en , \"Bản án, quyết định của Tòa án\"@vi ;\n    skos:definition \"A judgment or ruling issued by a court in a specific case, identified by its decision number (for example 38/2021/DS-PT), court and date.\"@en ;\n    skos:definition \"Bản án hoặc quyết định do Tòa án ban hành trong một vụ việc cụ thể, xác định bằng số (ví dụ 38/2021/DS-PT), Tòa án và ngày.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn); the VLOnto 1.0.0 knowledge graph has no data for this term.\"@en ,\n        \"Có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn); đồ thị tri thức VLOnto 1.0.0 chưa có dữ liệu cho khái niệm này.\"@vi .\n\nvlo:Judgment\n    a owl:Class ;\n    rdfs:subClassOf vlo:CourtDecision ;\n    rdfs:label \"Judgment\"@en , \"Bản án\"@vi ;\n    skos:definition \"A court decision that settles a case on its merits after a hearing (first instance, appeal, cassation or retrial).\"@en ;\n    skos:definition \"Quyết định của Tòa án giải quyết nội dung vụ án sau phiên tòa (sơ thẩm, phúc thẩm, giám đốc thẩm hoặc tái thẩm).\"@vi ;\n    rdfs:comment \"In the knowledge graph a decision is a Judgment when its number code does not start with QĐ.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn); the VLOnto 1.0.0 knowledge graph has no data for this term.\"@en ,\n        \"Có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn); đồ thị tri thức VLOnto 1.0.0 chưa có dữ liệu cho khái niệm này.\"@vi .\n\nvlo:CourtRuling\n    a owl:Class ;\n    rdfs:subClassOf vlo:CourtDecision ;\n    rdfs:label \"Court ruling\"@en , \"Quyết định của Tòa án\"@vi ;\n    skos:definition \"A decision of a court other than a judgment, for example recognising the parties' agreement or suspending a case.\"@en ;\n    skos:definition \"Quyết định của Tòa án không phải bản án, ví dụ quyết định công nhận sự thỏa thuận của các đương sự hoặc đình chỉ giải quyết vụ án.\"@vi ;\n    rdfs:comment \"In the knowledge graph a decision is a CourtRuling when its number code starts with QĐ (quyết định).\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn); the VLOnto 1.0.0 knowledge graph has no data for this term.\"@en ,\n        \"Có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn); đồ thị tri thức VLOnto 1.0.0 chưa có dữ liệu cho khái niệm này.\"@vi .\n\nvlo:Precedent\n    a owl:Class ;\n    rdfs:subClassOf vlo:JudicialDocument ;\n    rdfs:label \"Precedent\"@en , \"Án lệ\"@vi ;\n    skos:definition \"Reasoning or a ruling in a court decision that the Council of Judges of the Supreme People's Court has selected and the Chief Justice has published as a precedent for courts to follow; identified by its number, for example 04/2016/AL.\"@en ;\n    skos:definition \"Lập luận, phán quyết trong bản án, quyết định của Tòa án được Hội đồng Thẩm phán Tòa án nhân dân tối cao lựa chọn và được Chánh án công bố là án lệ để các Tòa án nghiên cứu, áp dụng; xác định bằng số, ví dụ 04/2016/AL.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn); the VLOnto 1.0.0 knowledge graph has no data for this term.\"@en ,\n        \"Có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn); đồ thị tri thức VLOnto 1.0.0 chưa có dữ liệu cho khái niệm này.\"@vi .\n\nvlo:Judgment owl:disjointWith vlo:CourtRuling .\nvlo:CourtDecision owl:disjointWith vlo:Precedent .\nvlo:JudicialDocument owl:disjointWith vlo:LegalDocument .\n\nvlo:CourtLevel\n    a owl:Class ;\n    rdfs:subClassOf skos:Concept ;\n    rdfs:label \"Court level\"@en , \"Cấp Tòa án\"@vi ;\n    skos:definition \"The level of a court in the court system: supreme, high, provincial, district or military.\"@en ;\n    skos:definition \"Cấp của Tòa án trong hệ thống: tối cao, cấp cao, cấp tỉnh, cấp huyện hoặc quân sự.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Its concepts are defined in the ontology; they classify court decisions, which are populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn). VLOnto 1.0.0 has no court decisions.\"@en ,\n        \"Các khái niệm được định nghĩa trong bản thể; chúng phân loại bản án, quyết định của Tòa án, có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn). VLOnto 1.0.0 chưa có bản án, quyết định.\"@vi .\n\nvlo:InstanceLevel\n    a owl:Class ;\n    rdfs:subClassOf skos:Concept ;\n    rdfs:label \"Instance level\"@en , \"Cấp xét xử\"@vi ;\n    skos:definition \"The procedural stage at which a decision is made: first instance, appeal, cassation review or retrial review.\"@en ;\n    skos:definition \"Giai đoạn tố tụng ra quyết định: sơ thẩm, phúc thẩm, giám đốc thẩm hoặc tái thẩm.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Its concepts are defined in the ontology; they classify court decisions, which are populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn). VLOnto 1.0.0 has no court decisions.\"@en ,\n        \"Các khái niệm được định nghĩa trong bản thể; chúng phân loại bản án, quyết định của Tòa án, có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn). VLOnto 1.0.0 chưa có bản án, quyết định.\"@vi .\n\nvlo:CaseCategory\n    a owl:Class ;\n    rdfs:subClassOf skos:Concept ;\n    rdfs:label \"Case category\"@en , \"Loại vụ việc\"@vi ;\n    skos:definition \"The legal domain of a case: civil, criminal, administrative, commercial, labour, marriage and family, bankruptcy or economic.\"@en ;\n    skos:definition \"Lĩnh vực của vụ việc: dân sự, hình sự, hành chính, kinh doanh thương mại, lao động, hôn nhân và gia đình, phá sản hoặc kinh tế.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Its concepts are defined in the ontology; they classify court decisions, which are populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn). VLOnto 1.0.0 has no court decisions.\"@en ,\n        \"Các khái niệm được định nghĩa trong bản thể; chúng phân loại bản án, quyết định của Tòa án, có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn). VLOnto 1.0.0 chưa có bản án, quyết định.\"@vi .\n\n# =====================================================================================================\n# Module: qa\n# =====================================================================================================\n\nvlo:LegalQuestion\n    a owl:Class ;\n    rdfs:subClassOf schema:Question ;\n    rdfs:label \"Legal question\"@en , \"Câu hỏi pháp luật\"@vi ;\n    skos:definition \"A published legal question from a legal Q&A service. The knowledge graph keeps its identifier, link, date and legal area, not its text.\"@en ;\n    skos:definition \"Câu hỏi pháp luật được đăng trên dịch vụ hỏi đáp pháp luật. Đồ thị chỉ lưu mã, liên kết, ngày và lĩnh vực, không lưu nội dung.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-qa .\n\nvlo:LegalAnswer\n    a owl:Class ;\n    rdfs:subClassOf schema:Answer ;\n    rdfs:label \"Legal answer\"@en , \"Câu trả lời pháp luật\"@vi ;\n    skos:definition \"The published answer to a legal question; in the knowledge graph it carries the citations of legal documents and provisions found in the answer, not its text.\"@en ;\n    skos:definition \"Câu trả lời đã đăng cho một câu hỏi pháp luật; trong đồ thị chỉ mang các trích dẫn văn bản và điều khoản, không lưu nội dung.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-qa .\n\nvlo:LegalQuestion owl:disjointWith vlo:LegalAnswer .\n\n# =====================================================================================================\n# Module: terminology\n# =====================================================================================================\n\nvlo:LegalTerm\n    a owl:Class ;\n    rdfs:subClassOf skos:Concept ;\n    rdfs:label \"Legal term\"@en , \"Thuật ngữ pháp lý\"@vi ;\n    skos:definition \"A term of Vietnamese legal language, organised as a SKOS concept with a Vietnamese preferred label, an English label (machine translation unless marked otherwise), a legal area, a status and related terms.\"@en ;\n    skos:definition \"Thuật ngữ trong ngôn ngữ pháp lý Việt Nam, được tổ chức thành khái niệm SKOS với nhãn tiếng Việt, nhãn tiếng Anh (bản dịch máy trừ khi ghi khác), lĩnh vực, tình trạng và các thuật ngữ liên quan.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-terminology .\n\n# =====================================================================================================\n# Module: news\n# =====================================================================================================\n\nvlo:LegalNewsArticle\n    a owl:Class ;\n    rdfs:subClassOf schema:NewsArticle ;\n    rdfs:label \"Legal news article\"@en , \"Bài viết tin tức pháp luật\"@vi ;\n    skos:definition \"A news, policy or advice article about law published by a legal information portal; the knowledge graph keeps its identifier, link, date, category and the legal documents it mentions.\"@en ;\n    skos:definition \"Bài viết tin tức, chính sách hoặc tư vấn về pháp luật trên cổng thông tin pháp luật; đồ thị lưu mã, liên kết, ngày, chuyên mục và các văn bản được nhắc đến.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-news .\n\nvlo:NewsCategory\n    a owl:Class ;\n    rdfs:subClassOf skos:Concept ;\n    rdfs:label \"News category\"@en , \"Chuyên mục tin tức\"@vi ;\n    skos:definition \"A section of a legal news portal, such as new policies or real estate.\"@en ;\n    skos:definition \"Chuyên mục của cổng tin tức pháp luật, như chính sách mới hay bất động sản.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-news .\n\n# =====================================================================================================\n# Module: classification\n# =====================================================================================================\n\nvlo:LegalArea\n    a owl:Class ;\n    rdfs:subClassOf skos:Concept ;\n    rdfs:label \"Legal area\"@en , \"Lĩnh vực pháp luật\"@vi ;\n    skos:definition \"A subject area of law used to classify documents, questions and terms, such as labour and wages or real estate.\"@en ;\n    skos:definition \"Lĩnh vực pháp luật dùng để phân loại văn bản, câu hỏi và thuật ngữ, ví dụ lao động - tiền lương hay bất động sản.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-classification .\n\nvlo:DocumentType\n    a owl:Class ;\n    rdfs:subClassOf skos:Concept , eli:ResourceType ;\n    rdfs:label \"Document type\"@en , \"Loại văn bản\"@vi ;\n    skos:definition \"A type of legal document, such as law, decree or circular; used as the value of eli:type_document.\"@en ;\n    skos:definition \"Loại văn bản pháp luật, ví dụ luật, nghị định, thông tư.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-classification .\n\nvlo:LegalForceRank\n    a owl:Class ;\n    rdfs:subClassOf skos:Concept ;\n    rdfs:label \"Legal-force rank\"@en , \"Thứ bậc hiệu lực pháp lý\"@vi ;\n    skos:definition \"A level in the hierarchy of legal force of Vietnamese normative documents, from the Constitution (level 0, highest) to circulars and ministerial decisions (level 5, lowest). An act cannot replace, repeal or amend an act of a higher level.\"@en ;\n    skos:definition \"Một bậc trong thứ bậc hiệu lực pháp lý của văn bản quy phạm pháp luật, từ Hiến pháp (bậc 0, cao nhất) đến thông tư và quyết định của bộ trưởng (bậc 5, thấp nhất).\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-classification .\n\n# =====================================================================================================\n# Module: provenance\n# =====================================================================================================\n\nvlo:SourceDataset\n    a owl:Class ;\n    rdfs:subClassOf prov:Entity ;\n    rdfs:label \"Source dataset\"@en , \"Bộ dữ liệu nguồn\"@vi ;\n    skos:definition \"A published dataset, pinned to a revision, from which knowledge-graph records were derived; carries its licence and attribution text.\"@en ;\n    skos:definition \"Bộ dữ liệu đã công bố, cố định theo phiên bản, là nguồn của các bản ghi trong đồ thị; kèm giấy phép và lời ghi nguồn.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provenance .\n\nvlo:ExtractionMethod\n    a owl:Class ;\n    rdfs:subClassOf prov:Plan , skos:Concept ;\n    rdfs:label \"Extraction method\"@en , \"Phương pháp trích xuất\"@vi ;\n    skos:definition \"A documented procedure that produced records or links of the knowledge graph, for example a rule set or a resolver strategy.\"@en ;\n    skos:definition \"Quy trình đã mô tả dùng để tạo bản ghi hoặc liên kết của đồ thị, ví dụ bộ luật trích xuất hoặc chiến lược phân giải.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provenance .\n\nvlo:EdgeSet\n    a owl:Class ;\n    rdfs:subClassOf prov:Entity ;\n    rdfs:label \"Edge set\"@en , \"Tập liên kết\"@vi ;\n    skos:definition \"The set of all knowledge-graph links of one property produced from one source, described with its size, the extraction methods used and the build that generated it. Per-link methods are kept in the parquet edge tables.\"@en ;\n    skos:definition \"Tập tất cả liên kết của một thuộc tính được tạo từ một nguồn, mô tả bằng số lượng, phương pháp trích xuất và lần xây dựng tạo ra nó.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provenance .\n\nvlo:BuildActivity\n    a owl:Class ;\n    rdfs:subClassOf prov:Activity ;\n    rdfs:label \"Build activity\"@en , \"Lần xây dựng đồ thị\"@vi ;\n    skos:definition \"One run of the VLOnto build pipeline that generated the knowledge-graph tables and RDF dumps.\"@en ;\n    skos:definition \"Một lần chạy quy trình xây dựng VLOnto tạo ra các bảng và tệp RDF của đồ thị.\"@vi ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provenance .\n\n# =====================================================================================================\n# Properties: documents and provisions\n# =====================================================================================================\n\nvlo:documentType a owl:ObjectProperty , owl:FunctionalProperty ;\n    rdfs:subPropertyOf eli:type_document ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range vlo:DocumentType ;\n    rdfs:label \"document type\"@en , \"loại văn bản\"@vi ;\n    skos:definition \"The type of a legal document as a concept of the DocumentType scheme.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-documents .\n\nvlo:documentNumber a owl:DatatypeProperty ;\n    rdfs:subPropertyOf eli:id_local ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range xsd:string ;\n    rdfs:label \"document number\"@en , \"số, ký hiệu văn bản\"@vi ;\n    skos:definition \"The official number and symbol of a legal document as printed in its header, for example 45/2019/QH14.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-documents .\n\nvlo:documentNumberKey a owl:DatatypeProperty ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range xsd:string ;\n    rdfs:label \"document number key\"@en , \"khóa số văn bản\"@vi ;\n    skos:definition \"A normalised lookup key of the document number (ASCII, upper case, unified separators, Đ written as D), used to match citations to documents.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-documents .\n\nvlo:title a owl:DatatypeProperty ;\n    rdfs:subPropertyOf dcterms:title ;\n    rdfs:range rdfs:Literal ;\n    rdfs:label \"title\"@en , \"tên văn bản\"@vi ;\n    skos:definition \"The Vietnamese title of a legal document, including its type and, for sub-statutory acts, its number.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-documents .\n\nvlo:issueDate a owl:DatatypeProperty ;\n    rdfs:subPropertyOf eli:date_document ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range xsd:date ;\n    rdfs:label \"issue date\"@en , \"ngày ban hành\"@vi ;\n    skos:definition \"The date on which a legal document was adopted or signed.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-documents .\n\nvlo:issuedBy a owl:ObjectProperty ;\n    rdfs:subPropertyOf eli:passed_by ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range vlo:IssuingBody ;\n    rdfs:label \"issued by\"@en , \"cơ quan ban hành\"@vi ;\n    skos:definition \"A body that issued a legal document; joint documents have several issuing bodies.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-agents .\n\nvlo:issuerCode a owl:DatatypeProperty ;\n    rdfs:domain vlo:IssuingBody ; rdfs:range xsd:string ;\n    rdfs:label \"issuer code\"@en , \"ký hiệu cơ quan ban hành\"@vi ;\n    skos:definition \"The abbreviation that identifies an issuing body in document numbers, written in ASCII upper case (for example BTC, BLDTBXH, TTG).\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-agents .\n\nvlo:legalForceRank a owl:ObjectProperty , owl:FunctionalProperty ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range vlo:LegalForceRank ;\n    rdfs:label \"legal-force rank\"@en , \"thứ bậc hiệu lực\"@vi ;\n    skos:definition \"The level of a legal document in the hierarchy of legal force, derived from its type and issuer (rule 5 of the validity rules v7).\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-classification .\n\nvlo:rankLevel a owl:DatatypeProperty ;\n    rdfs:domain vlo:LegalForceRank ; rdfs:range xsd:integer ;\n    rdfs:label \"rank level\"@en , \"bậc\"@vi ;\n    skos:definition \"The numeric level of a legal-force rank: 0 is the highest (Constitution), 5 the lowest.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-classification .\n\nvlo:legalArea a owl:ObjectProperty ;\n    rdfs:subPropertyOf dcterms:subject ;\n    rdfs:range vlo:LegalArea ;\n    rdfs:label \"legal area\"@en , \"lĩnh vực\"@vi ;\n    skos:definition \"The legal area under which a document, question or term is classified by its source.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-classification .\n\nvlo:isPartOf a owl:ObjectProperty ;\n    rdfs:subPropertyOf eli:is_part_of ;\n    owl:inverseOf vlo:hasPart ;\n    rdfs:domain vlo:Provision ; rdfs:range eli:LegalResource ;\n    rdfs:label \"is part of\"@en , \"thuộc\"@vi ;\n    skos:definition \"Links a provision to the unit that immediately contains it: a section, chapter, part, appendix, article, clause or the document itself.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provisions .\n\nvlo:hasPart a owl:ObjectProperty ;\n    rdfs:subPropertyOf eli:has_part ;\n    rdfs:domain eli:LegalResource ; rdfs:range vlo:Provision ;\n    rdfs:label \"has part\"@en , \"gồm\"@vi ;\n    skos:definition \"Inverse of vlo:isPartOf: links a document or provision to a provision it immediately contains. Not materialised in the RDF dumps.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provisions .\n\nvlo:inDocument a owl:ObjectProperty , owl:FunctionalProperty ;\n    rdfs:subPropertyOf eli:is_part_of ;\n    rdfs:domain vlo:Provision ; rdfs:range vlo:LegalDocument ;\n    rdfs:label \"in document\"@en , \"thuộc văn bản\"@vi ;\n    skos:definition \"Links a provision at any depth directly to the legal document that contains it.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provisions .\n\nvlo:provisionNumber a owl:DatatypeProperty ;\n    rdfs:subPropertyOf dcterms:identifier ;\n    rdfs:domain vlo:Provision ; rdfs:range xsd:string ;\n    rdfs:label \"provision number\"@en , \"số hiệu điều khoản\"@vi ;\n    skos:definition \"The number or letter of a provision within its parent: 35 or 5a for an article, 2 for a clause, a or đ for a point, III for a chapter, 1 for an appendix.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provisions .\n\nvlo:heading a owl:DatatypeProperty ;\n    rdfs:subPropertyOf dcterms:title ;\n    rdfs:domain vlo:Provision ; rdfs:range rdfs:Literal ;\n    rdfs:label \"heading\"@en , \"tên điều khoản\"@vi ;\n    skos:definition \"The heading of a provision as printed, cut at 200 characters (for example the article title or the chapter heading).\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provisions .\n\nvlo:position a owl:DatatypeProperty ;\n    rdfs:domain vlo:Provision ; rdfs:range xsd:integer ;\n    rdfs:label \"position\"@en , \"thứ tự\"@vi ;\n    skos:definition \"The 1-based order of a provision among the provisions of the same kind in its document, following the text.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provisions .\n\n# =====================================================================================================\n# Properties: validity and change\n# =====================================================================================================\n\nvlo:validityStatus a owl:ObjectProperty , owl:FunctionalProperty ;\n    rdfs:subPropertyOf eli:in_force ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range vlo:ValidityStatus ;\n    rdfs:label \"validity status\"@en , \"tình trạng hiệu lực\"@vi ;\n    skos:definition \"The validity of a legal document as of the build date of the knowledge graph.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:isInForce a owl:DatatypeProperty ;\n    rdfs:range xsd:boolean ;\n    rdfs:label \"is in force\"@en , \"còn hiệu lực\"@vi ;\n    skos:definition \"True if the document or term is known to be in force, false if known not to be in force; absent when unknown.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:effectiveDate a owl:DatatypeProperty ;\n    rdfs:subPropertyOf eli:first_date_entry_in_force ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range xsd:date ;\n    rdfs:label \"effective date\"@en , \"ngày có hiệu lực\"@vi ;\n    skos:definition \"The date on which a legal document enters into force (source metadata first, then the commencement article).\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:expiryDate a owl:DatatypeProperty ;\n    rdfs:subPropertyOf eli:date_no_longer_in_force ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range xsd:date ;\n    rdfs:label \"expiry date\"@en , \"ngày hết hiệu lực\"@vi ;\n    skos:definition \"The date from which a legal document is no longer in force, from the source status or from the effective date of the replacing or repealing act.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:sourceStatus a owl:DatatypeProperty ;\n    rdfs:range rdfs:Literal ;\n    rdfs:label \"source status\"@en , \"tình trạng theo nguồn\"@vi ;\n    skos:definition \"The validity status string as published by the source, in Vietnamese (for example 'Hết hiệu lực: 01/07/2025').\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:statusTextConflict a owl:DatatypeProperty ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range xsd:boolean ;\n    rdfs:label \"status-text conflict\"@en , \"mâu thuẫn trạng thái và văn bản\"@vi ;\n    skos:definition \"True when the source status says in force but an extracted relation says the document was replaced or repealed; such documents must be verified.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:validityEvidenceSource a owl:DatatypeProperty ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range xsd:string ;\n    rdfs:label \"validity evidence source\"@en , \"nguồn căn cứ hiệu lực\"@vi ;\n    skos:definition \"Which evidence determined the validity status: status, text, status+text or none.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:actingDocument a owl:ObjectProperty , owl:FunctionalProperty ;\n    rdfs:domain vlo:LegalChange ; rdfs:range vlo:LegalDocument ;\n    rdfs:label \"acting document\"@en , \"văn bản tác động\"@vi ;\n    skos:definition \"The legal document whose text makes the change (the newer act).\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:affectedDocument a owl:ObjectProperty , owl:FunctionalProperty ;\n    rdfs:domain vlo:LegalChange ; rdfs:range vlo:LegalDocument ;\n    rdfs:label \"affected document\"@en , \"văn bản bị tác động\"@vi ;\n    skos:definition \"The legal document that is replaced, amended, repealed or terminated by the change.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:changeKind a owl:ObjectProperty , owl:FunctionalProperty ;\n    rdfs:domain vlo:LegalChange ; rdfs:range vlo:ChangeKind ;\n    rdfs:label \"change kind\"@en , \"loại thay đổi\"@vi ;\n    skos:definition \"The kind of a legal change.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:changeEffectiveDate a owl:DatatypeProperty ;\n    rdfs:domain vlo:LegalChange ; rdfs:range xsd:date ;\n    rdfs:label \"change effective date\"@en , \"ngày thay đổi có hiệu lực\"@vi ;\n    skos:definition \"The date from which a legal change takes effect, normally the effective date of the acting document.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:mentionedDate a owl:DatatypeProperty ;\n    rdfs:domain vlo:LegalChange ; rdfs:range xsd:date ;\n    rdfs:label \"mentioned date\"@en , \"ngày được nêu\"@vi ;\n    skos:definition \"The issue date of the affected document as stated in the evidence sentence, when given; used to disambiguate numbers without a year.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:evidenceText a owl:DatatypeProperty ;\n    rdfs:domain vlo:LegalChange ; rdfs:range rdfs:Literal ;\n    rdfs:label \"evidence text\"@en , \"câu chứng cứ\"@vi ;\n    skos:definition \"The operative sentence of the acting document from which the change was extracted, quoted in Vietnamese and cut at 300 characters.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:ruleVersion a owl:DatatypeProperty ;\n    rdfs:domain vlo:LegalChange ; rdfs:range xsd:string ;\n    rdfs:label \"rule version\"@en , \"phiên bản quy tắc trích xuất\"@vi ;\n    skos:definition \"The version of the extraction rules that produced a legal change, for example v7.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:changes a owl:ObjectProperty ;\n    rdfs:subPropertyOf eli:changes ;\n    owl:inverseOf vlo:changedBy ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range vlo:LegalDocument ;\n    rdfs:label \"changes\"@en , \"thay đổi\"@vi ;\n    skos:definition \"Shortcut for any legal change: the subject document replaces, amends, repeals, partially repeals or partially terminates the object document.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:changedBy a owl:ObjectProperty ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range vlo:LegalDocument ;\n    rdfs:label \"changed by\"@en , \"bị thay đổi bởi\"@vi ;\n    skos:definition \"Inverse of vlo:changes. Not materialised in the RDF dumps.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:replaces a owl:ObjectProperty ;\n    rdfs:subPropertyOf vlo:changes , eli:repeals ;\n    owl:inverseOf vlo:replacedBy ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range vlo:LegalDocument ;\n    rdfs:label \"replaces\"@en , \"thay thế\"@vi ;\n    skos:definition \"The subject document replaces the object document as a whole, which then ceases to be in force (thay thế).\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:replacedBy a owl:ObjectProperty ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range vlo:LegalDocument ;\n    rdfs:label \"replaced by\"@en , \"được thay thế bởi\"@vi ;\n    skos:definition \"Inverse of vlo:replaces. Not materialised in the RDF dumps.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:amends a owl:ObjectProperty ;\n    rdfs:subPropertyOf vlo:changes , eli:amends ;\n    owl:inverseOf vlo:amendedBy ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range vlo:LegalDocument ;\n    rdfs:label \"amends\"@en , \"sửa đổi, bổ sung\"@vi ;\n    skos:definition \"The subject document amends or supplements some provisions of the object document (sửa đổi, bổ sung).\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:amendedBy a owl:ObjectProperty ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range vlo:LegalDocument ;\n    rdfs:label \"amended by\"@en , \"được sửa đổi, bổ sung bởi\"@vi ;\n    skos:definition \"Inverse of vlo:amends. Not materialised in the RDF dumps.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:repeals a owl:ObjectProperty ;\n    rdfs:subPropertyOf vlo:changes , eli:repeals ;\n    owl:inverseOf vlo:repealedBy ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range vlo:LegalDocument ;\n    rdfs:label \"repeals\"@en , \"bãi bỏ\"@vi ;\n    skos:definition \"The subject document repeals the object document as a whole without replacing it (bãi bỏ).\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:repealedBy a owl:ObjectProperty ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range vlo:LegalDocument ;\n    rdfs:label \"repealed by\"@en , \"bị bãi bỏ bởi\"@vi ;\n    skos:definition \"Inverse of vlo:repeals. Not materialised in the RDF dumps.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:partiallyRepeals a owl:ObjectProperty ;\n    rdfs:subPropertyOf vlo:changes ;\n    owl:inverseOf vlo:partiallyRepealedBy ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range vlo:LegalDocument ;\n    rdfs:label \"partially repeals\"@en , \"bãi bỏ một phần\"@vi ;\n    skos:definition \"The subject document repeals some articles, clauses, points or contents of the object document, which otherwise stays in force.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:partiallyRepealedBy a owl:ObjectProperty ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range vlo:LegalDocument ;\n    rdfs:label \"partially repealed by\"@en , \"bị bãi bỏ một phần bởi\"@vi ;\n    skos:definition \"Inverse of vlo:partiallyRepeals. Not materialised in the RDF dumps.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:partiallyTerminates a owl:ObjectProperty ;\n    rdfs:subPropertyOf vlo:changes ;\n    owl:inverseOf vlo:partiallyTerminatedBy ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range vlo:LegalDocument ;\n    rdfs:label \"partially terminates\"@en , \"làm hết hiệu lực một phần\"@vi ;\n    skos:definition \"The subject document declares that some provisions of the object document cease to be in force (hết hiệu lực một phần).\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:partiallyTerminatedBy a owl:ObjectProperty ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range vlo:LegalDocument ;\n    rdfs:label \"partially terminated by\"@en , \"bị làm hết hiệu lực một phần bởi\"@vi ;\n    skos:definition \"Inverse of vlo:partiallyTerminates. Not materialised in the RDF dumps.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\n# =====================================================================================================\n# Properties: citation and legal basis\n# =====================================================================================================\n\nvlo:refersTo a owl:ObjectProperty ;\n    rdfs:subPropertyOf dcterms:references ;\n    rdfs:label \"refers to\"@en , \"dẫn chiếu\"@vi ;\n    skos:definition \"The most general VLOnto reference link: a work (legal document, provision, court decision, answer or news article) refers to a legal resource or judicial document. Specialised by the citation, basis, application and mention properties.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-citation-basis .\n\nvlo:cites a owl:ObjectProperty ;\n    rdfs:subPropertyOf vlo:refersTo , eli:cites ;\n    rdfs:domain eli:LegalResource ; rdfs:range eli:LegalResource ;\n    rdfs:label \"cites\"@en , \"trích dẫn\"@vi ;\n    skos:definition \"A legal document, or one of its articles, cites another legal document or a provision of it. Self-references and anaphoric references are not included.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-citation-basis .\n\nvlo:citesParentLaw a owl:ObjectProperty ;\n    rdfs:subPropertyOf vlo:cites ;\n    rdfs:domain eli:LegalResource ; rdfs:range eli:LegalResource ;\n    rdfs:label \"cites parent law\"@en , \"trích dẫn luật gốc\"@vi ;\n    skos:definition \"A citation that the source dataset marks as a reference to the parent law of the citing document, that is, the law the citing document details or implements.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-citation-basis .\n\nvlo:legalBasis a owl:ObjectProperty ;\n    rdfs:subPropertyOf vlo:refersTo , eli:based_on ;\n    owl:inverseOf vlo:isLegalBasisOf ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range vlo:LegalDocument ;\n    rdfs:label \"legal basis\"@en , \"căn cứ pháp lý\"@vi ;\n    skos:definition \"The object document is a legal basis on which the subject document was issued, as listed in the 'Căn cứ ...' recitals of its preamble or in the source's parent-acts field. The object never has a lower legal-force rank than the subject.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-citation-basis .\n\nvlo:isLegalBasisOf a owl:ObjectProperty ;\n    rdfs:domain vlo:LegalDocument ; rdfs:range vlo:LegalDocument ;\n    rdfs:label \"is legal basis of\"@en , \"là căn cứ của\"@vi ;\n    skos:definition \"Inverse of vlo:legalBasis. Not materialised in the RDF dumps.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-citation-basis .\n\n# =====================================================================================================\n# Properties: judiciary\n# =====================================================================================================\n\nvlo:decidedBy a owl:ObjectProperty ;\n    rdfs:subPropertyOf dcterms:creator ;\n    rdfs:domain vlo:CourtDecision ; rdfs:range vlo:Court ;\n    rdfs:label \"decided by\"@en , \"Tòa án ban hành\"@vi ;\n    skos:definition \"The court that issued a court decision.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn); the VLOnto 1.0.0 knowledge graph has no data for this term.\"@en ,\n        \"Có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn); đồ thị tri thức VLOnto 1.0.0 chưa có dữ liệu cho khái niệm này.\"@vi .\n\nvlo:courtLevel a owl:ObjectProperty ;\n    rdfs:range vlo:CourtLevel ;\n    rdfs:label \"court level\"@en , \"cấp Tòa án\"@vi ;\n    skos:definition \"The level of the court that issued a decision, or of a court.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn); the VLOnto 1.0.0 knowledge graph has no data for this term.\"@en ,\n        \"Có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn); đồ thị tri thức VLOnto 1.0.0 chưa có dữ liệu cho khái niệm này.\"@vi .\n\nvlo:instanceLevel a owl:ObjectProperty ;\n    rdfs:domain vlo:CourtDecision ; rdfs:range vlo:InstanceLevel ;\n    rdfs:label \"instance level\"@en , \"cấp xét xử\"@vi ;\n    skos:definition \"The procedural stage at which a court decision was made.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn); the VLOnto 1.0.0 knowledge graph has no data for this term.\"@en ,\n        \"Có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn); đồ thị tri thức VLOnto 1.0.0 chưa có dữ liệu cho khái niệm này.\"@vi .\n\nvlo:caseCategory a owl:ObjectProperty ;\n    rdfs:domain vlo:JudicialDocument ; rdfs:range vlo:CaseCategory ;\n    rdfs:label \"case category\"@en , \"loại vụ việc\"@vi ;\n    skos:definition \"The legal domain of the case decided or of the precedent.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn); the VLOnto 1.0.0 knowledge graph has no data for this term.\"@en ,\n        \"Có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn); đồ thị tri thức VLOnto 1.0.0 chưa có dữ liệu cho khái niệm này.\"@vi .\n\nvlo:decisionNumber a owl:DatatypeProperty ;\n    rdfs:subPropertyOf dcterms:identifier ;\n    rdfs:domain vlo:CourtDecision ; rdfs:range xsd:string ;\n    rdfs:label \"decision number\"@en , \"số bản án, quyết định\"@vi ;\n    skos:definition \"The number of a court decision as issued, for example 38/2021/DS-PT. Numbers are unique only within one court.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn); the VLOnto 1.0.0 knowledge graph has no data for this term.\"@en ,\n        \"Có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn); đồ thị tri thức VLOnto 1.0.0 chưa có dữ liệu cho khái niệm này.\"@vi .\n\nvlo:decisionCode a owl:DatatypeProperty ;\n    rdfs:domain vlo:CourtDecision ; rdfs:range xsd:string ;\n    rdfs:label \"decision code\"@en , \"ký hiệu bản án, quyết định\"@vi ;\n    skos:definition \"The symbol part of a decision number that encodes case domain and stage, for example DS-PT (civil, appeal) or QĐST-HNGĐ (first-instance ruling, marriage and family).\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn); the VLOnto 1.0.0 knowledge graph has no data for this term.\"@en ,\n        \"Có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn); đồ thị tri thức VLOnto 1.0.0 chưa có dữ liệu cho khái niệm này.\"@vi .\n\nvlo:decisionDate a owl:DatatypeProperty ;\n    rdfs:subPropertyOf dcterms:date ;\n    rdfs:domain vlo:CourtDecision ; rdfs:range xsd:date ;\n    rdfs:label \"decision date\"@en , \"ngày tuyên án, ra quyết định\"@vi ;\n    skos:definition \"The date on which a court decision was issued.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn); the VLOnto 1.0.0 knowledge graph has no data for this term.\"@en ,\n        \"Có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn); đồ thị tri thức VLOnto 1.0.0 chưa có dữ liệu cho khái niệm này.\"@vi .\n\nvlo:precedentNumber a owl:DatatypeProperty ;\n    rdfs:subPropertyOf dcterms:identifier ;\n    rdfs:domain vlo:Precedent ; rdfs:range xsd:string ;\n    rdfs:label \"precedent number\"@en , \"số án lệ\"@vi ;\n    skos:definition \"The national number of a precedent, for example 04/2016/AL.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn); the VLOnto 1.0.0 knowledge graph has no data for this term.\"@en ,\n        \"Có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn); đồ thị tri thức VLOnto 1.0.0 chưa có dữ liệu cho khái niệm này.\"@vi .\n\nvlo:selectedFrom a owl:ObjectProperty ;\n    rdfs:subPropertyOf prov:wasDerivedFrom ;\n    rdfs:domain vlo:Precedent ; rdfs:range vlo:CourtDecision ;\n    rdfs:label \"selected from\"@en , \"được lựa chọn từ\"@vi ;\n    skos:definition \"The court decision whose reasoning or ruling was selected as the precedent.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn); the VLOnto 1.0.0 knowledge graph has no data for this term.\"@en ,\n        \"Có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn); đồ thị tri thức VLOnto 1.0.0 chưa có dữ liệu cho khái niệm này.\"@vi .\n\nvlo:appliesProvision a owl:ObjectProperty ;\n    rdfs:subPropertyOf vlo:refersTo ;\n    rdfs:domain vlo:JudicialDocument ; rdfs:range vlo:Provision ;\n    rdfs:label \"applies provision\"@en , \"áp dụng điều khoản\"@vi ;\n    skos:definition \"A court decision cites an article, clause or point of a legal document as applied or relied on.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn); the VLOnto 1.0.0 knowledge graph has no data for this term.\"@en ,\n        \"Có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn); đồ thị tri thức VLOnto 1.0.0 chưa có dữ liệu cho khái niệm này.\"@vi .\n\nvlo:appliesDocument a owl:ObjectProperty ;\n    rdfs:subPropertyOf vlo:refersTo ;\n    rdfs:domain vlo:JudicialDocument ; rdfs:range vlo:LegalDocument ;\n    rdfs:label \"applies document\"@en , \"áp dụng văn bản\"@vi ;\n    skos:definition \"A court decision cites a legal document as a whole, or a provision of it that is not available as an article node.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn); the VLOnto 1.0.0 knowledge graph has no data for this term.\"@en ,\n        \"Có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn); đồ thị tri thức VLOnto 1.0.0 chưa có dữ liệu cho khái niệm này.\"@vi .\n\nvlo:citesCase a owl:ObjectProperty ;\n    rdfs:subPropertyOf vlo:refersTo ;\n    rdfs:domain vlo:JudicialDocument ; rdfs:range vlo:JudicialDocument ;\n    rdfs:label \"cites case\"@en , \"viện dẫn bản án\"@vi ;\n    skos:definition \"A court decision refers to another court decision (for example the first-instance judgment under appeal) or to a precedent.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn); the VLOnto 1.0.0 knowledge graph has no data for this term.\"@en ,\n        \"Có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn); đồ thị tri thức VLOnto 1.0.0 chưa có dữ liệu cho khái niệm này.\"@vi .\n\nvlo:appliesPrecedent a owl:ObjectProperty ;\n    rdfs:subPropertyOf vlo:citesCase ;\n    rdfs:domain vlo:JudicialDocument ; rdfs:range vlo:Precedent ;\n    rdfs:label \"applies precedent\"@en , \"áp dụng án lệ\"@vi ;\n    skos:definition \"A court decision cites a precedent by its number.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn); the VLOnto 1.0.0 knowledge graph has no data for this term.\"@en ,\n        \"Có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn); đồ thị tri thức VLOnto 1.0.0 chưa có dữ liệu cho khái niệm này.\"@vi .\n\n# =====================================================================================================\n# Properties: Q&A, terminology, news\n# =====================================================================================================\n\nvlo:hasAnswer a owl:ObjectProperty , owl:FunctionalProperty ;\n    rdfs:subPropertyOf schema:acceptedAnswer ;\n    rdfs:domain vlo:LegalQuestion ; rdfs:range vlo:LegalAnswer ;\n    rdfs:label \"has answer\"@en , \"có câu trả lời\"@vi ;\n    skos:definition \"Links a legal question to its published answer.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-qa .\n\nvlo:answerCitesProvision a owl:ObjectProperty ;\n    rdfs:subPropertyOf vlo:refersTo , schema:citation ;\n    rdfs:domain vlo:LegalAnswer ; rdfs:range vlo:Provision ;\n    rdfs:label \"answer cites provision\"@en , \"câu trả lời trích dẫn điều khoản\"@vi ;\n    skos:definition \"A legal answer cites an article, clause or point of a legal document.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-qa .\n\nvlo:answerCitesDocument a owl:ObjectProperty ;\n    rdfs:subPropertyOf vlo:refersTo , schema:citation ;\n    rdfs:domain vlo:LegalAnswer ; rdfs:range vlo:LegalDocument ;\n    rdfs:label \"answer cites document\"@en , \"câu trả lời trích dẫn văn bản\"@vi ;\n    skos:definition \"A legal answer cites a legal document by its number.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-qa .\n\nvlo:publishedDate a owl:DatatypeProperty ;\n    rdfs:subPropertyOf dcterms:issued ;\n    rdfs:range xsd:date ;\n    rdfs:label \"published date\"@en , \"ngày đăng\"@vi ;\n    skos:definition \"The date on which a question, answer or news article was published by its source.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-qa .\n\nvlo:relatedTerm a owl:ObjectProperty , owl:SymmetricProperty ;\n    rdfs:subPropertyOf skos:related ;\n    rdfs:domain vlo:LegalTerm ; rdfs:range vlo:LegalTerm ;\n    rdfs:label \"related term\"@en , \"thuật ngữ liên quan\"@vi ;\n    skos:definition \"A legal term listed by the source as related to another term.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-terminology .\n\nvlo:englishLabelSource a owl:DatatypeProperty ;\n    rdfs:domain vlo:LegalTerm ; rdfs:range xsd:string ;\n    rdfs:label \"English label source\"@en , \"nguồn nhãn tiếng Anh\"@vi ;\n    skos:definition \"Provenance of the English label of a term: 'mt' for machine translation, 'site' for an English name given by the source site.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-terminology .\n\nvlo:translationModel a owl:DatatypeProperty ;\n    rdfs:domain vlo:LegalTerm ; rdfs:range xsd:string ;\n    rdfs:label \"translation model\"@en , \"mô hình dịch\"@vi ;\n    skos:definition \"Identifier of the model that machine-translated the English label, as recorded by the source dataset.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-terminology .\n\nvlo:mentionsDocument a owl:ObjectProperty ;\n    rdfs:subPropertyOf vlo:refersTo , schema:mentions ;\n    rdfs:domain vlo:LegalNewsArticle ; rdfs:range vlo:LegalDocument ;\n    rdfs:label \"mentions document\"@en , \"nhắc đến văn bản\"@vi ;\n    skos:definition \"A news article mentions a legal document by its number.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-news .\n\nvlo:newsCategory a owl:ObjectProperty ;\n    rdfs:domain vlo:LegalNewsArticle ; rdfs:range vlo:NewsCategory ;\n    rdfs:label \"news category\"@en , \"chuyên mục\"@vi ;\n    skos:definition \"The section of the portal in which a news article was published.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-news .\n\n# =====================================================================================================\n# Properties: provenance\n# =====================================================================================================\n\nvlo:sourceDataset a owl:ObjectProperty ;\n    rdfs:subPropertyOf dcterms:source ;\n    rdfs:range vlo:SourceDataset ;\n    rdfs:label \"source dataset\"@en , \"bộ dữ liệu nguồn\"@vi ;\n    skos:definition \"The source dataset from which a knowledge-graph record was derived.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provenance .\n\nvlo:sourceId a owl:DatatypeProperty ;\n    rdfs:subPropertyOf dcterms:identifier ;\n    rdfs:range xsd:string ;\n    rdfs:label \"source identifier\"@en , \"mã trong nguồn\"@vi ;\n    skos:definition \"The identifier of the record in its source dataset (for example the vbpl document id 333670 or the cbba doc_name).\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provenance .\n\nvlo:sourceUrl a owl:DatatypeProperty ;\n    rdfs:subPropertyOf schema:url ;\n    rdfs:range xsd:anyURI ;\n    rdfs:label \"source URL\"@en , \"đường dẫn nguồn\"@vi ;\n    skos:definition \"The web address of the record at its original publisher, where its full text can be read.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provenance .\n\nvlo:datasetRevision a owl:DatatypeProperty ;\n    rdfs:domain vlo:SourceDataset ; rdfs:range xsd:string ;\n    rdfs:label \"dataset revision\"@en , \"phiên bản bộ dữ liệu\"@vi ;\n    skos:definition \"The commit hash of the dataset revision that was used.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provenance .\n\nvlo:licenceLabel a owl:DatatypeProperty ;\n    rdfs:domain vlo:SourceDataset ; rdfs:range xsd:string ;\n    rdfs:label \"licence label\"@en , \"nhãn giấy phép\"@vi ;\n    skos:definition \"The licence identifier given in the card of the source dataset, for example cc-by-4.0 or other.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provenance .\n\nvlo:attributionText a owl:DatatypeProperty ;\n    rdfs:domain vlo:SourceDataset ; rdfs:range rdfs:Literal ;\n    rdfs:label \"attribution text\"@en , \"lời ghi nguồn\"@vi ;\n    skos:definition \"The attribution that must accompany material derived from the dataset.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provenance .\n\nvlo:inclusionPolicy a owl:DatatypeProperty ;\n    rdfs:domain vlo:SourceDataset ; rdfs:range rdfs:Literal ;\n    rdfs:label \"inclusion policy\"@en , \"chính sách sử dụng\"@vi ;\n    skos:definition \"What VLOnto takes from the dataset and what it leaves out, following the dataset licence.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provenance .\n\nvlo:extractionMethod a owl:ObjectProperty ;\n    rdfs:range vlo:ExtractionMethod ;\n    rdfs:label \"extraction method\"@en , \"phương pháp trích xuất\"@vi ;\n    skos:definition \"The extraction method that produced a legal change or the links of an edge set.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provenance .\n\nvlo:edgeProperty a owl:ObjectProperty ;\n    rdfs:domain vlo:EdgeSet ;\n    rdfs:label \"edge property\"@en , \"thuộc tính liên kết\"@vi ;\n    skos:definition \"The property used by all links of an edge set.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provenance .\n\nvlo:edgeCount a owl:DatatypeProperty ;\n    rdfs:domain vlo:EdgeSet ; rdfs:range xsd:integer ;\n    rdfs:label \"edge count\"@en , \"số liên kết\"@vi ;\n    skos:definition \"The number of links in an edge set.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provenance .\n\nvlo:validityAsOf a owl:DatatypeProperty ;\n    rdfs:domain vlo:BuildActivity ; rdfs:range xsd:date ;\n    rdfs:label \"validity as of\"@en , \"hiệu lực tính đến ngày\"@vi ;\n    skos:definition \"The reference date at which document validity was computed.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provenance .\n\nvlo:softwareVersion a owl:DatatypeProperty ;\n    rdfs:domain vlo:BuildActivity ; rdfs:range xsd:string ;\n    rdfs:label \"software version\"@en , \"phiên bản phần mềm\"@vi ;\n    skos:definition \"The version of the VLOnto build code used by a build activity.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-provenance .\n\nprov:wasDerivedFrom a owl:ObjectProperty ; rdfs:label \"was derived from (PROV)\"@en ; rdfs:isDefinedBy <http://www.w3.org/ns/prov-o#> .\n\n# =====================================================================================================\n# Concept schemes. Closed vocabularies are defined here; data-driven schemes (legal areas, term areas,\n# news categories, the legal-term glossary) are declared here and populated by the knowledge graph.\n# =====================================================================================================\n\nvlo:shortcutProperty a owl:AnnotationProperty ;\n    rdfs:label \"shortcut property\"@en , \"thuộc tính rút gọn\"@vi ;\n    skos:definition \"Links a change kind to the direct document-to-document property that represents the same change.\"@en ;\n    rdfs:isDefinedBy <https://tmquan.github.io/VLOnto/ontology> ; vlo:module vlo:module-validity-change .\n\nvlo:DocumentTypeScheme a skos:ConceptScheme ;\n    rdfs:label \"Document types\"@en , \"Loại văn bản\"@vi ;\n    skos:definition \"The ten types of normative legal documents in the scope of VLOnto.\"@en ;\n    vlo:module vlo:module-classification .\n\nvlo:doctype-constitution a vlo:DocumentType , owl:NamedIndividual ; skos:inScheme vlo:DocumentTypeScheme ; skos:topConceptOf vlo:DocumentTypeScheme ;\n    skos:notation \"HP\" ; skos:prefLabel \"Constitution\"@en , \"Hiến pháp\"@vi ; skos:definition \"Document type of the Constitution.\"@en .\nvlo:doctype-code a vlo:DocumentType , owl:NamedIndividual ; skos:inScheme vlo:DocumentTypeScheme ; skos:topConceptOf vlo:DocumentTypeScheme ;\n    skos:notation \"BL\" ; skos:prefLabel \"Code\"@en , \"Bộ luật\"@vi ; skos:definition \"Document type of codes adopted by the National Assembly.\"@en .\nvlo:doctype-law a vlo:DocumentType , owl:NamedIndividual ; skos:inScheme vlo:DocumentTypeScheme ; skos:topConceptOf vlo:DocumentTypeScheme ;\n    skos:notation \"L\" ; skos:prefLabel \"Law\"@en , \"Luật\"@vi ; skos:definition \"Document type of laws adopted by the National Assembly.\"@en .\nvlo:doctype-ordinance a vlo:DocumentType , owl:NamedIndividual ; skos:inScheme vlo:DocumentTypeScheme ; skos:topConceptOf vlo:DocumentTypeScheme ;\n    skos:notation \"PL\" ; skos:prefLabel \"Ordinance\"@en , \"Pháp lệnh\"@vi ; skos:definition \"Document type of ordinances of the National Assembly Standing Committee.\"@en .\nvlo:doctype-resolution a vlo:DocumentType , owl:NamedIndividual ; skos:inScheme vlo:DocumentTypeScheme ; skos:topConceptOf vlo:DocumentTypeScheme ;\n    skos:notation \"NQ\" ; skos:prefLabel \"Resolution\"@en , \"Nghị quyết\"@vi ; skos:definition \"Document type of normative resolutions.\"@en .\nvlo:doctype-joint-resolution a vlo:DocumentType , owl:NamedIndividual ; skos:inScheme vlo:DocumentTypeScheme ; skos:topConceptOf vlo:DocumentTypeScheme ;\n    skos:notation \"NQLT\" ; skos:prefLabel \"Joint resolution\"@en , \"Nghị quyết liên tịch\"@vi ; skos:definition \"Document type of joint resolutions.\"@en .\nvlo:doctype-decree a vlo:DocumentType , owl:NamedIndividual ; skos:inScheme vlo:DocumentTypeScheme ; skos:topConceptOf vlo:DocumentTypeScheme ;\n    skos:notation \"NĐ\" ; skos:prefLabel \"Decree\"@en , \"Nghị định\"@vi ; skos:definition \"Document type of Government decrees.\"@en .\nvlo:doctype-decision a vlo:DocumentType , owl:NamedIndividual ; skos:inScheme vlo:DocumentTypeScheme ; skos:topConceptOf vlo:DocumentTypeScheme ;\n    skos:notation \"QĐ\" ; skos:prefLabel \"Decision\"@en , \"Quyết định\"@vi ; skos:definition \"Document type of normative decisions.\"@en .\nvlo:doctype-circular a vlo:DocumentType , owl:NamedIndividual ; skos:inScheme vlo:DocumentTypeScheme ; skos:topConceptOf vlo:DocumentTypeScheme ;\n    skos:notation \"TT\" ; skos:prefLabel \"Circular\"@en , \"Thông tư\"@vi ; skos:definition \"Document type of circulars.\"@en .\nvlo:doctype-joint-circular a vlo:DocumentType , owl:NamedIndividual ; skos:inScheme vlo:DocumentTypeScheme ; skos:topConceptOf vlo:DocumentTypeScheme ;\n    skos:notation \"TTLT\" ; skos:prefLabel \"Joint circular\"@en , \"Thông tư liên tịch\"@vi ; skos:definition \"Document type of joint circulars.\"@en .\n\nvlo:ValidityStatusScheme a skos:ConceptScheme ;\n    rdfs:label \"Validity statuses\"@en , \"Tình trạng hiệu lực\"@vi ;\n    skos:definition \"The eight validity values computed by the validity rules v7 as of the knowledge-graph date.\"@en ;\n    vlo:module vlo:module-validity-change .\n\nvlo:validity-in-force a vlo:ValidityStatus , owl:NamedIndividual ; skos:inScheme vlo:ValidityStatusScheme ; skos:topConceptOf vlo:ValidityStatusScheme ;\n    skos:notation \"in_force\" ; skos:prefLabel \"in force\"@en , \"còn hiệu lực\"@vi ;\n    skos:definition \"The source status says the document is in force and no amending act was extracted.\"@en .\nvlo:validity-in-force-amended a vlo:ValidityStatus , owl:NamedIndividual ; skos:inScheme vlo:ValidityStatusScheme ; skos:topConceptOf vlo:ValidityStatusScheme ;\n    skos:notation \"in_force_amended\" ; skos:prefLabel \"in force, amended\"@en , \"còn hiệu lực, đã được sửa đổi\"@vi ;\n    skos:definition \"The source status says the document is in force and at least one amending act was extracted.\"@en .\nvlo:validity-presumed-in-force-amended a vlo:ValidityStatus , owl:NamedIndividual ; skos:inScheme vlo:ValidityStatusScheme ; skos:topConceptOf vlo:ValidityStatusScheme ;\n    skos:notation \"presumed_in_force_amended\" ; skos:prefLabel \"presumed in force, amended\"@en , \"được cho là còn hiệu lực, đã được sửa đổi\"@vi ;\n    skos:definition \"The source gives no status; the document was amended but no replacement or repeal was extracted.\"@en .\nvlo:validity-superseded a vlo:ValidityStatus , owl:NamedIndividual ; skos:inScheme vlo:ValidityStatusScheme ; skos:topConceptOf vlo:ValidityStatusScheme ;\n    skos:notation \"superseded\" ; skos:prefLabel \"superseded\"@en , \"đã bị thay thế hoặc bãi bỏ\"@vi ;\n    skos:definition \"An extracted relation says the document was replaced or repealed.\"@en .\nvlo:validity-expired a vlo:ValidityStatus , owl:NamedIndividual ; skos:inScheme vlo:ValidityStatusScheme ; skos:topConceptOf vlo:ValidityStatusScheme ;\n    skos:notation \"expired\" ; skos:prefLabel \"no longer in force\"@en , \"hết hiệu lực\"@vi ;\n    skos:definition \"The source status says the document is no longer in force.\"@en .\nvlo:validity-not-yet-effective a vlo:ValidityStatus , owl:NamedIndividual ; skos:inScheme vlo:ValidityStatusScheme ; skos:topConceptOf vlo:ValidityStatusScheme ;\n    skos:notation \"not_yet_effective\" ; skos:prefLabel \"not yet in force\"@en , \"chưa có hiệu lực\"@vi ;\n    skos:definition \"The effective date is after the as-of date of the knowledge graph.\"@en .\nvlo:validity-not-applicable a vlo:ValidityStatus , owl:NamedIndividual ; skos:inScheme vlo:ValidityStatusScheme ; skos:topConceptOf vlo:ValidityStatusScheme ;\n    skos:notation \"not_applicable\" ; skos:prefLabel \"no longer applicable\"@en , \"không còn phù hợp\"@vi ;\n    skos:definition \"The source status says the document is no longer applicable (Không còn phù hợp).\"@en .\nvlo:validity-unknown a vlo:ValidityStatus , owl:NamedIndividual ; skos:inScheme vlo:ValidityStatusScheme ; skos:topConceptOf vlo:ValidityStatusScheme ;\n    skos:notation \"unknown\" ; skos:prefLabel \"unknown\"@en , \"chưa xác định\"@vi ;\n    skos:definition \"Neither a source status nor an extracted change relation is available; the validity is unknown, not assumed.\"@en .\n\nvlo:ChangeKindScheme a skos:ConceptScheme ;\n    rdfs:label \"Change kinds\"@en , \"Loại thay đổi\"@vi ;\n    skos:definition \"The five kinds of legal change extracted by the validity rules v7.\"@en ;\n    vlo:module vlo:module-validity-change .\n\nvlo:change-replaced a vlo:ChangeKind , owl:NamedIndividual ; skos:inScheme vlo:ChangeKindScheme ; skos:topConceptOf vlo:ChangeKindScheme ;\n    skos:notation \"replaced\" ; skos:prefLabel \"replaced\"@en , \"thay thế\"@vi ; vlo:shortcutProperty vlo:replaces ;\n    skos:definition \"The affected document is replaced as a whole by the acting document.\"@en .\nvlo:change-amended a vlo:ChangeKind , owl:NamedIndividual ; skos:inScheme vlo:ChangeKindScheme ; skos:topConceptOf vlo:ChangeKindScheme ;\n    skos:notation \"amended\" ; skos:prefLabel \"amended\"@en , \"sửa đổi, bổ sung\"@vi ; vlo:shortcutProperty vlo:amends ;\n    skos:definition \"Some provisions of the affected document are amended or supplemented.\"@en .\nvlo:change-repealed a vlo:ChangeKind , owl:NamedIndividual ; skos:inScheme vlo:ChangeKindScheme ; skos:topConceptOf vlo:ChangeKindScheme ;\n    skos:notation \"repealed\" ; skos:prefLabel \"repealed\"@en , \"bãi bỏ\"@vi ; vlo:shortcutProperty vlo:repeals ;\n    skos:definition \"The affected document is repealed as a whole.\"@en .\nvlo:change-partially-repealed a vlo:ChangeKind , owl:NamedIndividual ; skos:inScheme vlo:ChangeKindScheme ; skos:topConceptOf vlo:ChangeKindScheme ;\n    skos:notation \"partially_repealed\" ; skos:prefLabel \"partially repealed\"@en , \"bãi bỏ một phần\"@vi ; vlo:shortcutProperty vlo:partiallyRepeals ;\n    skos:definition \"Some provisions or contents of the affected document are repealed.\"@en .\nvlo:change-partially-expired a vlo:ChangeKind , owl:NamedIndividual ; skos:inScheme vlo:ChangeKindScheme ; skos:topConceptOf vlo:ChangeKindScheme ;\n    skos:notation \"partially_expired\" ; skos:prefLabel \"partially terminated\"@en , \"hết hiệu lực một phần\"@vi ; vlo:shortcutProperty vlo:partiallyTerminates ;\n    skos:definition \"Some provisions of the affected document are declared no longer in force.\"@en .\n\nvlo:LegalForceRankScheme a skos:ConceptScheme ;\n    rdfs:label \"Legal-force ranks\"@en , \"Thứ bậc hiệu lực pháp lý\"@vi ;\n    skos:definition \"Six levels of legal force used by the validity rules (rule 5) and as the vertical layer of the 3D legal network.\"@en ;\n    vlo:module vlo:module-classification .\n\nvlo:rank-0 a vlo:LegalForceRank , owl:NamedIndividual ; skos:inScheme vlo:LegalForceRankScheme ; skos:topConceptOf vlo:LegalForceRankScheme ; skos:notation \"0\" ; vlo:rankLevel 0 ;\n    skos:prefLabel \"Constitution\"@en , \"Hiến pháp\"@vi ; skos:definition \"Highest legal force: the Constitution.\"@en .\nvlo:rank-1 a vlo:LegalForceRank , owl:NamedIndividual ; skos:inScheme vlo:LegalForceRankScheme ; skos:topConceptOf vlo:LegalForceRankScheme ; skos:notation \"1\" ; vlo:rankLevel 1 ;\n    skos:prefLabel \"Codes, laws and National Assembly resolutions\"@en , \"Bộ luật, luật, nghị quyết của Quốc hội\"@vi ; skos:definition \"Acts of the National Assembly other than the Constitution.\"@en .\nvlo:rank-2 a vlo:LegalForceRank , owl:NamedIndividual ; skos:inScheme vlo:LegalForceRankScheme ; skos:topConceptOf vlo:LegalForceRankScheme ; skos:notation \"2\" ; vlo:rankLevel 2 ;\n    skos:prefLabel \"Ordinances and Standing Committee resolutions\"@en , \"Pháp lệnh, nghị quyết của Ủy ban Thường vụ Quốc hội\"@vi ; skos:definition \"Acts of the Standing Committee of the National Assembly.\"@en .\nvlo:rank-3 a vlo:LegalForceRank , owl:NamedIndividual ; skos:inScheme vlo:LegalForceRankScheme ; skos:topConceptOf vlo:LegalForceRankScheme ; skos:notation \"3\" ; vlo:rankLevel 3 ;\n    skos:prefLabel \"Decrees, joint resolutions and other resolutions\"@en , \"Nghị định, nghị quyết liên tịch và nghị quyết khác\"@vi ; skos:definition \"Government decrees, joint resolutions and resolutions of the Government or the Council of Judges.\"@en .\nvlo:rank-4 a vlo:LegalForceRank , owl:NamedIndividual ; skos:inScheme vlo:LegalForceRankScheme ; skos:topConceptOf vlo:LegalForceRankScheme ; skos:notation \"4\" ; vlo:rankLevel 4 ;\n    skos:prefLabel \"Prime Minister decisions\"@en , \"Quyết định của Thủ tướng Chính phủ\"@vi ; skos:definition \"Normative decisions of the Prime Minister.\"@en .\nvlo:rank-5 a vlo:LegalForceRank , owl:NamedIndividual ; skos:inScheme vlo:LegalForceRankScheme ; skos:topConceptOf vlo:LegalForceRankScheme ; skos:notation \"5\" ; vlo:rankLevel 5 ;\n    skos:prefLabel \"Circulars, joint circulars and other decisions\"@en , \"Thông tư, thông tư liên tịch và quyết định khác\"@vi ; skos:definition \"Lowest legal force in scope: circulars, joint circulars and decisions of ministers and other heads of central bodies.\"@en .\n\nvlo:CourtLevelScheme a skos:ConceptScheme ;\n    rdfs:label \"Court levels\"@en , \"Cấp Tòa án\"@vi ;\n    skos:definition \"Levels of the Vietnamese court system as recorded by the court-decision datasets.\"@en ;\n    vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Its concepts are defined in the ontology; they classify court decisions, which are populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn). VLOnto 1.0.0 has no court decisions.\"@en ,\n        \"Các khái niệm được định nghĩa trong bản thể; chúng phân loại bản án, quyết định của Tòa án, có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn). VLOnto 1.0.0 chưa có bản án, quyết định.\"@vi .\n\nvlo:court-level-supreme a vlo:CourtLevel , owl:NamedIndividual ; skos:inScheme vlo:CourtLevelScheme ; skos:topConceptOf vlo:CourtLevelScheme ;\n    skos:notation \"Supreme\" ; skos:prefLabel \"Supreme People's Court\"@en , \"Tòa án nhân dân tối cao\"@vi ; skos:definition \"The highest court.\"@en .\nvlo:court-level-high a vlo:CourtLevel , owl:NamedIndividual ; skos:inScheme vlo:CourtLevelScheme ; skos:topConceptOf vlo:CourtLevelScheme ;\n    skos:notation \"High\" ; skos:prefLabel \"High People's Court\"@en , \"Tòa án nhân dân cấp cao\"@vi ; skos:definition \"The three high courts (Hà Nội, Đà Nẵng, Hồ Chí Minh City).\"@en .\nvlo:court-level-provincial a vlo:CourtLevel , owl:NamedIndividual ; skos:inScheme vlo:CourtLevelScheme ; skos:topConceptOf vlo:CourtLevelScheme ;\n    skos:notation \"Provincial\" ; skos:prefLabel \"provincial court\"@en , \"Tòa án nhân dân cấp tỉnh\"@vi ; skos:definition \"Courts of provinces and centrally run cities.\"@en .\nvlo:court-level-district a vlo:CourtLevel , owl:NamedIndividual ; skos:inScheme vlo:CourtLevelScheme ; skos:topConceptOf vlo:CourtLevelScheme ;\n    skos:notation \"District\" ; skos:prefLabel \"district court\"@en , \"Tòa án nhân dân cấp huyện\"@vi ; skos:definition \"Courts of districts, towns and provincial cities (regional courts after the 2025 reform).\"@en .\nvlo:court-level-military a vlo:CourtLevel , owl:NamedIndividual ; skos:inScheme vlo:CourtLevelScheme ; skos:topConceptOf vlo:CourtLevelScheme ;\n    skos:notation \"Military\" ; skos:prefLabel \"military court\"@en , \"Tòa án quân sự\"@vi ; skos:definition \"Courts of the military court system.\"@en .\n\nvlo:InstanceLevelScheme a skos:ConceptScheme ;\n    rdfs:label \"Instance levels\"@en , \"Cấp xét xử\"@vi ;\n    skos:definition \"Procedural stages at which court decisions are made.\"@en ;\n    vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Its concepts are defined in the ontology; they classify court decisions, which are populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn). VLOnto 1.0.0 has no court decisions.\"@en ,\n        \"Các khái niệm được định nghĩa trong bản thể; chúng phân loại bản án, quyết định của Tòa án, có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn). VLOnto 1.0.0 chưa có bản án, quyết định.\"@vi .\n\nvlo:instance-first-instance a vlo:InstanceLevel , owl:NamedIndividual ; skos:inScheme vlo:InstanceLevelScheme ; skos:topConceptOf vlo:InstanceLevelScheme ;\n    skos:notation \"First-instance\" ; skos:prefLabel \"first instance\"@en , \"sơ thẩm\"@vi ; skos:definition \"First hearing of a case.\"@en .\nvlo:instance-appellate a vlo:InstanceLevel , owl:NamedIndividual ; skos:inScheme vlo:InstanceLevelScheme ; skos:topConceptOf vlo:InstanceLevelScheme ;\n    skos:notation \"Appellate\" ; skos:prefLabel \"appeal\"@en , \"phúc thẩm\"@vi ; skos:definition \"Hearing of an appeal against a first-instance decision that is not yet legally effective.\"@en .\nvlo:instance-cassation a vlo:InstanceLevel , owl:NamedIndividual ; skos:inScheme vlo:InstanceLevelScheme ; skos:topConceptOf vlo:InstanceLevelScheme ;\n    skos:notation \"Cassation\" ; skos:prefLabel \"cassation review\"@en , \"giám đốc thẩm\"@vi ; skos:definition \"Review of a legally effective decision because of a serious violation of law.\"@en .\nvlo:instance-retrial a vlo:InstanceLevel , owl:NamedIndividual ; skos:inScheme vlo:InstanceLevelScheme ; skos:topConceptOf vlo:InstanceLevelScheme ;\n    skos:notation \"Retrial\" ; skos:prefLabel \"retrial review\"@en , \"tái thẩm\"@vi ; skos:definition \"Review of a legally effective decision because of newly discovered facts.\"@en .\n\nvlo:CaseCategoryScheme a skos:ConceptScheme ;\n    rdfs:label \"Case categories\"@en , \"Loại vụ việc\"@vi ;\n    skos:definition \"Legal domains of cases as recorded by the court-decision datasets.\"@en ;\n    vlo:module vlo:module-judiciary ;\n    skos:scopeNote \"Its concepts are defined in the ontology; they classify court decisions, which are populated from VLOnto 2.0 (court datasets anle-toaan-gov-vn and cbba-toaan-gov-vn). VLOnto 1.0.0 has no court decisions.\"@en ,\n        \"Các khái niệm được định nghĩa trong bản thể; chúng phân loại bản án, quyết định của Tòa án, có dữ liệu từ VLOnto 2.0 (các bộ dữ liệu tòa án anle-toaan-gov-vn và cbba-toaan-gov-vn). VLOnto 1.0.0 chưa có bản án, quyết định.\"@vi .\n\nvlo:case-civil a vlo:CaseCategory , owl:NamedIndividual ; skos:inScheme vlo:CaseCategoryScheme ; skos:topConceptOf vlo:CaseCategoryScheme ;\n    skos:notation \"Civil\" ; skos:prefLabel \"civil\"@en , \"dân sự\"@vi ; skos:definition \"Civil cases and matters.\"@en .\nvlo:case-criminal a vlo:CaseCategory , owl:NamedIndividual ; skos:inScheme vlo:CaseCategoryScheme ; skos:topConceptOf vlo:CaseCategoryScheme ;\n    skos:notation \"Criminal\" ; skos:prefLabel \"criminal\"@en , \"hình sự\"@vi ; skos:definition \"Criminal cases.\"@en .\nvlo:case-administrative a vlo:CaseCategory , owl:NamedIndividual ; skos:inScheme vlo:CaseCategoryScheme ; skos:topConceptOf vlo:CaseCategoryScheme ;\n    skos:notation \"Administrative\" ; skos:prefLabel \"administrative\"@en , \"hành chính\"@vi ; skos:definition \"Administrative cases against decisions or acts of state bodies.\"@en .\nvlo:case-commercial a vlo:CaseCategory , owl:NamedIndividual ; skos:inScheme vlo:CaseCategoryScheme ; skos:topConceptOf vlo:CaseCategoryScheme ;\n    skos:notation \"Commercial\" ; skos:prefLabel \"business and commercial\"@en , \"kinh doanh, thương mại\"@vi ; skos:definition \"Business and commercial disputes.\"@en .\nvlo:case-labour a vlo:CaseCategory , owl:NamedIndividual ; skos:inScheme vlo:CaseCategoryScheme ; skos:topConceptOf vlo:CaseCategoryScheme ;\n    skos:notation \"Labor\" ; skos:prefLabel \"labour\"@en , \"lao động\"@vi ; skos:definition \"Labour disputes.\"@en .\nvlo:case-marriage-family a vlo:CaseCategory , owl:NamedIndividual ; skos:inScheme vlo:CaseCategoryScheme ; skos:topConceptOf vlo:CaseCategoryScheme ;\n    skos:notation \"Marriage & Family\" ; skos:prefLabel \"marriage and family\"@en , \"hôn nhân và gia đình\"@vi ; skos:definition \"Marriage and family cases, including divorce.\"@en .\nvlo:case-bankruptcy a vlo:CaseCategory , owl:NamedIndividual ; skos:inScheme vlo:CaseCategoryScheme ; skos:topConceptOf vlo:CaseCategoryScheme ;\n    skos:notation \"Bankruptcy\" ; skos:prefLabel \"bankruptcy\"@en , \"phá sản\"@vi ; skos:definition \"Bankruptcy proceedings.\"@en .\nvlo:case-economic a vlo:CaseCategory , owl:NamedIndividual ; skos:inScheme vlo:CaseCategoryScheme ; skos:topConceptOf vlo:CaseCategoryScheme ;\n    skos:notation \"Economic\" ; skos:prefLabel \"economic\"@en , \"kinh tế\"@vi ; skos:definition \"Economic cases (category used before commercial cases were introduced).\"@en .\n\nvlo:ExtractionMethodScheme a skos:ConceptScheme ;\n    rdfs:label \"Extraction methods\"@en , \"Phương pháp trích xuất\"@vi ;\n    skos:definition \"Procedures that produced VLOnto records and links; the notation is the value used in the method columns of the parquet edge tables.\"@en ;\n    vlo:module vlo:module-provenance .\n\nvlo:method-source-metadata a vlo:ExtractionMethod , owl:NamedIndividual ; skos:inScheme vlo:ExtractionMethodScheme ; skos:notation \"source-metadata\" ;\n    skos:prefLabel \"source metadata\"@en , \"siêu dữ liệu nguồn\"@vi ; skos:definition \"Value taken from a structured field of the source dataset after cleaning (clean.py).\"@en .\nvlo:method-chunk-parser a vlo:ExtractionMethod , owl:NamedIndividual ; skos:inScheme vlo:ExtractionMethodScheme ; skos:notation \"chunk-parser\" ;\n    skos:prefLabel \"article parser\"@en , \"bộ tách điều\"@vi ; skos:definition \"Article, appendix, chapter and section structure parsed from the cleaned text with the sequence rules of chunk.py.\"@en .\nvlo:method-validity-rules-v7 a vlo:ExtractionMethod , owl:NamedIndividual ; skos:inScheme vlo:ExtractionMethodScheme ; skos:notation \"validity-rules-v7\" ;\n    skos:prefLabel \"validity rules v7\"@en , \"bộ luật hiệu lực v7\"@vi ; skos:definition \"Replace, amend, repeal and termination relations extracted from operative clauses of the acting document (validity.py rules v7: operative-clause and description filters, date-matched year-less numbers, partial subjects, legal-hierarchy filter, status-first precedence); manual precision 29/30 on a sample.\"@en .\nvlo:method-docnum-key a vlo:ExtractionMethod , owl:NamedIndividual ; skos:inScheme vlo:ExtractionMethodScheme ; skos:notation \"docnum-key\" ;\n    skos:prefLabel \"document-number key\"@en , \"khóa số văn bản\"@vi ; skos:definition \"A cited document number normalised with docnum_key and matched to an in-scope document; when several documents share the key, the one of the cited type issued last on or before the citing date is taken.\"@en .\nvlo:method-law-name-year a vlo:ExtractionMethod , owl:NamedIndividual ; skos:inScheme vlo:ExtractionMethodScheme ; skos:notation \"law-name-year\" ;\n    skos:prefLabel \"law name and year\"@en , \"tên luật và năm\"@vi ; skos:definition \"A code, law, ordinance or constitution cited by type and name, matched diacritic-insensitively to titles of in-scope documents; the version issued or effective in the cited year, or else the latest version in force at the citing date, is taken.\"@en .\nvlo:method-unique-document-of-type a vlo:ExtractionMethod , owl:NamedIndividual ; skos:inScheme vlo:ExtractionMethodScheme ; skos:notation \"unique-document-of-type\" ;\n    skos:prefLabel \"unique document of type\"@en , \"văn bản duy nhất cùng loại\"@vi ; skos:definition \"A provision cited without a law name is attached to the only document of that type cited in the same record.\"@en .\nvlo:method-answer-text-number a vlo:ExtractionMethod , owl:NamedIndividual ; skos:inScheme vlo:ExtractionMethodScheme ; skos:notation \"answer-text-number\" ;\n    skos:prefLabel \"answer text, number\"@en , \"nội dung trả lời, số văn bản\"@vi ; skos:definition \"The document is read from the answer text right after 'Điều N' and matched by its number.\"@en .\nvlo:method-answer-text-name a vlo:ExtractionMethod , owl:NamedIndividual ; skos:inScheme vlo:ExtractionMethodScheme ; skos:notation \"answer-text-name\" ;\n    skos:prefLabel \"answer text, name\"@en , \"nội dung trả lời, tên luật\"@vi ; skos:definition \"The document is read from the answer text right after 'Điều N' and matched by law name and year.\"@en .\nvlo:method-citation-field-name a vlo:ExtractionMethod , owl:NamedIndividual ; skos:inScheme vlo:ExtractionMethodScheme ; skos:notation \"citation-field-name\" ;\n    skos:prefLabel \"citation field, name\"@en , \"trường trích dẫn, tên luật\"@vi ; skos:definition \"The document is matched from the law-name and year fields of the source citation.\"@en .\nvlo:method-parent-acts a vlo:ExtractionMethod , owl:NamedIndividual ; skos:inScheme vlo:ExtractionMethodScheme ; skos:notation \"parent-acts\" ;\n    skos:prefLabel \"parent-acts field\"@en , \"trường văn bản căn cứ\"@vi ; skos:definition \"Legal basis taken from the parent_acts field of the vbpl dataset and resolved by number or name.\"@en .\nvlo:method-preamble-citation a vlo:ExtractionMethod , owl:NamedIndividual ; skos:inScheme vlo:ExtractionMethodScheme ; skos:notation \"preamble-citation\" ;\n    skos:prefLabel \"preamble citation\"@en , \"trích dẫn phần căn cứ\"@vi ; skos:definition \"Legal basis taken from citations that the vbpl dataset locates in the preamble of the citing document, kept only when the cited document does not have a lower legal-force rank than the citing one.\"@en .\nvlo:method-constitution-preamble a vlo:ExtractionMethod , owl:NamedIndividual ; skos:inScheme vlo:ExtractionMethodScheme ; skos:notation \"constitution-preamble\" ;\n    skos:prefLabel \"Constitution in the preamble\"@en , \"Hiến pháp trong phần căn cứ\"@vi ; skos:definition \"Legal basis on the Constitution, which has no number and therefore no citation record: 'Căn cứ Hiến pháp ...' before Article 1 is linked to the constitution named by year or by its amending resolution, otherwise to the one in force on the citing document's issue date.\"@en .\nvlo:method-case-number-date a vlo:ExtractionMethod , owl:NamedIndividual ; skos:inScheme vlo:ExtractionMethodScheme ; skos:notation \"case-number-date\" ;\n    skos:prefLabel \"case number and date\"@en , \"số và ngày bản án\"@vi ; skos:definition \"A cited decision is matched by number, year, symbol and the exact date written next to the citation; the court named next to the citation, when present, must also match. Without a named court the match is kept only when the courts of both decisions are known and are the same court, lie in the same province, or the citing court is the Supreme Court or the High Court of the cited court's region.\"@en .\nvlo:method-case-number-court a vlo:ExtractionMethod , owl:NamedIndividual ; skos:inScheme vlo:ExtractionMethodScheme ; skos:notation \"case-number-court\" ;\n    skos:prefLabel \"case number and court\"@en , \"số bản án và Tòa án\"@vi ; skos:definition \"A cited decision is matched by number, year, symbol and the court named next to the citation.\"@en .\nvlo:method-precedent-number a vlo:ExtractionMethod , owl:NamedIndividual ; skos:inScheme vlo:ExtractionMethodScheme ; skos:notation \"precedent-number\" ;\n    skos:prefLabel \"precedent number\"@en , \"số án lệ\"@vi ; skos:definition \"A precedent cited by its national number NN/YYYY/AL.\"@en .\nvlo:method-docnum-regex a vlo:ExtractionMethod , owl:NamedIndividual ; skos:inScheme vlo:ExtractionMethodScheme ; skos:notation \"docnum-regex\" ;\n    skos:prefLabel \"document-number pattern\"@en , \"mẫu số văn bản\"@vi ; skos:definition \"Document numbers of the form N/YYYY/CODE found by regular expression in a text and resolved by docnum_key.\"@en .\nvlo:method-court-name a vlo:ExtractionMethod , owl:NamedIndividual ; skos:inScheme vlo:ExtractionMethodScheme ; skos:notation \"court-name\" ;\n    skos:prefLabel \"court name\"@en , \"tên Tòa án\"@vi ; skos:definition \"The issuing court taken from the court field of the source, or from the judgment header when the field holds only the generic name; anonymised names are not used.\"@en .\nvlo:method-issuer-code a vlo:ExtractionMethod , owl:NamedIndividual ; skos:inScheme vlo:ExtractionMethodScheme ; skos:notation \"issuer-code\" ;\n    skos:prefLabel \"issuer code\"@en , \"ký hiệu cơ quan\"@vi ; skos:definition \"Issuing bodies read from the symbol part of the document number (for example TT-BTC gives BTC), falling back to the issuer field of the source.\"@en .\n\nvlo:LegalAreaScheme a skos:ConceptScheme ;\n    rdfs:label \"Legal areas (documents and Q&A)\"@en , \"Lĩnh vực pháp luật (văn bản và hỏi đáp)\"@vi ;\n    skos:definition \"The 27 legal areas used by the document and Q&A datasets; populated by the knowledge graph.\"@en ;\n    vlo:module vlo:module-classification .\n\nvlo:TermAreaScheme a skos:ConceptScheme ;\n    rdfs:label \"Legal areas (terminology)\"@en , \"Lĩnh vực pháp luật (thuật ngữ)\"@vi ;\n    skos:definition \"The legal areas used by the terminology dataset; areas with the same name as a document area are the same concept. Populated by the knowledge graph.\"@en ;\n    vlo:module vlo:module-classification .\n\nvlo:NewsCategoryScheme a skos:ConceptScheme ;\n    rdfs:label \"News categories\"@en , \"Chuyên mục tin tức\"@vi ;\n    skos:definition \"Sections of the legal news portal; populated by the knowledge graph.\"@en ;\n    vlo:module vlo:module-news .\n\nvlo:LegalTermScheme a skos:ConceptScheme ;\n    rdfs:label \"Vietnamese legal terminology\"@en , \"Thuật ngữ pháp lý Việt Nam\"@vi ;\n    skos:definition \"The glossary of legal terms derived from the terminology dataset; populated by the knowledge graph.\"@en ;\n    vlo:module vlo:module-terminology .\n";
